[274] = {"水坝危机", {"阿什兰·暗石要你回去见主工程师辛德维尔七世，把有关这种炸药的新发现告诉他。"}},
[275] = {"大地上的脓疱", {"杀死12只沼泽爬行者，然后向湿地的绿色守卫者雷希耶尔复命。"}},
[276] = {"践踏之爪", {"杀死15名藓皮豺狼人和10名混血藓皮豺狼人，然后向湿地的绿色守卫者雷希耶尔复命。"}},
[277] = {"火焰管制", {"给绿色守卫者雷希耶尔带回9块粗制打火石。"}},
[278] = {"水坝危机", {"主工程师辛德维尔七世要你收集一份潜伏者的毒液，一块莫格罗什水晶和一滴鳄鱼的眼泪。"}},
[279] = {"海中的鱼人", {"杀掉12个蓝腮鱼人。","","杀掉高布勒尔并砍下它的头。","","将高布勒尔的头颅交给米奈希尔港的卡尔·波兰。"}},
[280] = {"水坝危机", {"主工程师辛德维尔七世要你游到水坝底部，找到装着炸药的木桶，然后把拆弹剂放进去，阻止将要发生的爆炸。"}},
[281] = {"夺回雕像", {"搜索海边鱼人村落中的木箱和木桶。"}},
[282] = {"森内尔的观察站", {"和巡山人萨鲁斯谈一谈。"}},
[283] = {"水坝危机", {"拆弹剂看来已经产生了效果。你可以回去向主工程师辛德维尔七世汇报这个好消息了。"}},
[284] = {"继续搜寻", {"搜索米奈希尔雕塑。"}},
[285] = {"搜寻雕像", {"继续在鱼人村落中搜寻米奈希尔雕像的踪迹。"}},
[286] = {"归还雕像", {"将米奈希尔雕像还给卡尔·波兰。"}},
[287] = {"霜鬃巨魔要塞", {"侦查霜鬃巨魔要塞，替卡拉诺斯的森内尔·白须杀掉5个霜鬃猎头者。"}},
[288] = {"第三舰队", {"为大副菲兹莫斯买一份壶装蜜酒。"}},
[289] = {"被诅咒的船员", {"消灭13名被诅咒的水手、5名被诅咒的水兵和大副斯涅利格。把斯涅利格的鼻烟盒交给米奈希尔港的大副菲兹莫斯。"}},
[290] = {"解除诅咒", {"从哈林多尔船长那里拿到无畏号的保险箱钥匙。","","用钥匙打开无畏号上的保险箱。"}},
[291] = {"森内尔的报告", {"把森内尔的报告交给铁炉堡的参议员巴林·红石。"}},
[292] = {"帕雷斯之眼", {"把被诅咒的帕雷斯之眼交给戈罗林·钢眉。"}},
[293] = {"净化帕雷斯之眼", {"把被诅咒的帕雷斯之眼交给大主教本尼迪塔斯。他就在暴风城的光明大教堂里。"}},
[294] = {"奥莫尔的复仇", {"维尔加挖掘场的奥莫尔·铁衣要求你杀死10只杂斑迅猛龙和10只杂斑尖啸龙。"}},
[295] = {"奥莫尔的复仇", {"奥莫尔·铁衣要求你杀死10只杂斑镰爪龙和10只杂斑刺喉龙，然后返回维尔加挖掘场向他复命。"}},
[296] = {"奥莫尔的复仇", {"维尔加挖掘场的奥莫尔·铁衣要求你杀死萨尔图斯，并在任务完成之后带着它的一只爪子向他复命。"}},
[297] = {"收集石像", {"收集8个小石像，把它们交给麦格玛尔·落斧。"}},
[298] = {"挖掘进度报告", {"把铁环挖掘场的进度报告带给塞尔萨玛的吉恩·角盔。"}},
[299] = {"发现历史", {"勘察员维尔加要求你在挖掘场中搜索4块石板的碎片，它们是阿度斯碎片、莫德尔碎片、高尔姆碎片和奈尔鲁碎片。"}},
[301] = {"向铁炉堡报告", {"把铁环挖掘场的进度报告交给勘察员塔伯斯·雷矛。"}},
[302] = {"铁环的火药", {"和塞尔萨玛的吉恩·角盔谈一谈。"}},
[303] = {"黑铁战争", {"丹莫德的莫特雷·加玛森要求你消灭15名黑铁矮人、5名黑铁隧道工、5名黑铁破坏者和5名黑铁爆破手。"}},
[304] = {"艰巨的任务", {"杀死邪恶的巴尔加拉斯，把他的耳朵带给丹莫德外的布莱德·长须。"}},
[305] = {"寻找挖掘队", {"塔雷尔·石纹要求你到挖掘场里去找到麦琳·石纹。"}},
[306] = {"寻找挖掘队", {"把麦琳的信件交给塔雷尔·石纹复命。"}},
[307] = {"肮脏的爪子", {"到银泉矿洞去收集4套矿工装备，然后向巡山人卡尔·雷矛复命。"}},
[308] = {"加文的爱好", nil},
[309] = {"护送货物", {"确保把米兰和货物送到挖掘场，然后通知勘察员基恩萨·铁环。"}},
[310] = {"针锋相对", {"到卡拉诺斯的雷酒酿造厂酒窖里去，把一桶雷霆啤酒换成热麦酒。"}},
[311] = {"向马莱斯回报", {"把雷霆麦酒交给烈酒村的马莱斯·麦酒。"}},
[312] = {"马克格拉恩的干肉", {"从冰须的洞穴里拿回装有马克格拉恩的干肉的储藏柜。"}},
[313] = {"灰色洞穴", {"收集8束雪怪的鬃毛，把它们交给驾驶员迪恩·石轮。"}},
[314] = {"保护牲畜", {"山羊农场的鲁德拉·冻石要你杀了瓦加什，并且把它的牙齿给她带回去。"}},
[315] = {"完美烈酒", {"收集6束微光草，把它们交给烈酒村的雷杰德·麦酒。"}},
[317] = {"贝尔丁的补给", {"收集4大块野猪肉和2张厚熊皮，把它们交给钢架补给站的驾驶员贝隆·风箱。"}},
[318] = {"艾沃沙酒", {"从烈酒村的雷杰德·麦酒那里弄到一桶艾沃沙酒。"}},
[319] = {"艾沃沙酒", {"杀掉6头冰爪熊、8只老峭壁野猪和8只雪豹，然后回到烈酒村的雷杰德·麦酒那里。"}},
[320] = {"艾沃沙酒", {"把这桶艾沃沙酒交给钢架补给站的驾驶员贝隆·风箱。"}},
[321] = {"光铸铁", {"搜索飞翔鱼鹰号的残骸。"}},
[322] = {"格瑞曼德·艾尔默", {"将这箱光铸铁锭交给格瑞曼德·艾尔默。"}},
[323] = {"证明你的实力", {"杀掉15个骷髅袭击者、3个骷髅医师和3个骷髅看守，然后回来见斯温。"}},
[324] = {"丢失的铁锭", {"收集5块光铸铁锭，把它们交给湿地的戈罗林·钢眉。"}},
[325] = {"整装待发", {"现在你已经得到了强大的武器，去向暮色森林的斯温复命吧。"}},
[328] = {"隐藏的钥匙", {"使用黄铜钥匙打开书呆子赫罗德的保险箱。"}},
[329] = {"找出内鬼！", {"将沾泥的便笺交给叛军营地里的多伦上尉。"}},
[330] = {"巡逻时间表", {"与塞斯曼下士谈一谈。"}},
[331] = {"向多伦报告", {"与多伦上尉谈一谈。"}},
[332] = {"酒店的广告", {"到加林纳酒店去, 将酒票交给苏泽塔·加林纳以换一瓶免费的酒。"}},
[333] = {"哈兰需要供货", {"找到运河裁缝店，并将哈兰·巴格雷的布料订单带给雷玛·施涅德。"}},
[334] = {"萨尔曼的针线包", {"到暴风城法师区的拉尔森服装店去，将针线包带给萨尔曼·斯涅德。"}},
[335] = {"名酿", {"黑爪加尔德斯要求你从夜色镇给他摘1朵蒂罗亚之泪，再从湿地给他采一块麝鼠根。"}},
[336] = {"名酿", {"将黑爪烈酒带给祈愿厅里的维沙克公爵。"}},
[337] = {"一本破旧的历史书", {"把《暴风城的历史》这本书还给暴风城图书馆。"}},
[338] = {"荆棘谷的青山", {"收集《荆棘谷的青山》的手稿中丢失的页面。在集齐四章书之后，将它们还给巴尼尔·石罐。"}},
[339] = {"荆棘谷的青山 - 第一章", {"将奈辛瓦里的小说《荆棘谷的青山》的第1页，第4页，第6页和第8页带给巴尼尔·石罐以凑齐第一章。"}},
[340] = {"荆棘谷的青山 - 第二章", {"将奈辛瓦里的小说《荆棘谷的青山》的第10页，第11页，第14页和第16页带给巴尼尔·石罐以凑齐第二章。"}},
[341] = {"荆棘谷的青山 - 第三章", {"将奈辛瓦里的小说《荆棘谷的青山》的第18页，第20页，第21页和第24页带给巴尼尔·石罐以凑齐第三章。"}},
[342] = {"荆棘谷的青山 - 第四章", {"将奈辛瓦里的小说《荆棘谷的青山》的第25页，第26页和第27页带给巴尼尔·石罐以凑齐第四章。"}},
[343] = {"关于坚韧的演讲", {"到暴风城堡的皇家图书馆去与米尔顿·西弗交谈，他将会为你找到克里斯托弗修士所需要的关于冶金学的书。"}},
[344] = {"帕克斯顿修士", {"与北郡修道院的帕克斯顿修士谈一谈。"}},
[345] = {"墨水短缺", {"与湖畔镇的工头奥斯洛交谈，并向他要一些瑞斯班矿石。"}},
[346] = {"克里斯托弗的书", {"回到教堂广场，将《金属的延展性》交给克里斯托弗修士。"}},
[347] = {"瑞斯班矿石", {"收集5袋瑞斯班矿石，把它们带给北郡图书馆的帕克斯顿修士。"}},
[348] = {"荆棘谷热疫", {"找到巫医安巴格瓦并要求他召唤出野人莫克，然后将野人莫克的心脏交给芬·菲兹拉克。"}},
[349] = {"荆棘谷热疫", nil},
[350] = {"老朋友", {"与暴风城的埃林·提亚斯谈一谈。"}},
[351] = {"寻找OOX-17/TN！", {"把定位器带到奥格索普的母体机器人那里。"}},
[353] = {"雷矛的包裹", {"把给卡尔·雷矛的包裹交给洛克莫丹北部哨塔里的巡山人卡尔·雷矛。"}},
[354] = {"阿加曼德家族", {"把格里高的遗骸、妮萨的残骸和萨尔曼的遗骸交给布瑞尔的库勒曼·法席恩。"}},
[355] = {"与塞弗伦交谈", {"与布瑞尔的执政官塞弗伦谈一谈。"}},
[356] = {"巡查后方", {"杀死8个可怕的血僵尸和8个游荡的幽灵，然后向亡灵卫兵林奈汇报。"}},
[357] = {"巫妖的身份", {"把巫妖的法术书带给幽暗城的比索·埃斯沙德。"}},
[358] = {"盗墓贼", {"杀死腐皮盗墓贼和混血腐皮豺狼人。","","给布瑞尔的执政官塞弗伦带回8瓶防腐剂。"}},
[359] = {"亡灵卫兵的职责", {"与亡灵卫兵林奈谈一谈。"}},
[360] = {"向塞弗伦回报", {"向布瑞尔的执政官塞弗伦报告。"}},
[361] = {"未寄出的信件", {"找到伊维特·法席恩，将萨尔曼·阿加曼德的信交给她。"}},
[362] = {"闹鬼的磨坊", {"杀死代弗林·阿加曼德，然后将代弗林的遗骸交给布瑞尔的库勒曼·法席恩。"}},
[363] = {"突然醒来", {"和暗影牧师萨维斯谈一谈。"}},
[364] = {"无脑的僵尸", {"暗影牧师萨维斯让你杀掉8个无脑的僵尸和8个丑陋的僵尸。"}},
[365] = {"悲伤之地", {"从位于布瑞尔西边、丧钟镇北边的农场中偷10颗南瓜来，把它们交给布瑞尔的药剂师乔汉。"}},
[366] = {"归还书籍", {"到冈瑟尔居住的小岛去归还他的法术书。"}},
[367] = {"新的瘟疫", {"布瑞尔镇里的药剂师乔汉要求你收集5瓶黑暗犬的血液。"}},
[368] = {"新的瘟疫", {"布瑞尔镇里的药剂师乔汉要求你收集5片提瑞斯法林地的邪鳍鱼人的鳞片。"}},
[369] = {"新的瘟疫", {"布瑞尔镇里的药剂师乔汉要你去收集4份邪恶的夜行蜘蛛的毒液样本。"}},
[370] = {"与血色十字军的战争", {"布瑞尔的执行官塞加德要求你杀掉派瑞恩队长、3名血色狂热者和3名血色传教士。"}},
[371] = {"与血色十字军的战争", {"布瑞尔的执行官塞加德要求你杀掉瓦松队长和5名血色苦行修士。"}},
[372] = {"与血色十字军的战争", {"布瑞尔的执行官塞加德要求你刺杀麦拉其队长及他的两名保镖。"}},
[373] = {"未寄出的信", {"将艾德温·范克里夫的信交给巴隆斯·阿历克斯顿。"}},
[374] = {"死亡证明", {"给布瑞尔的亡灵卫兵伯吉斯带回10枚血色十字军徽记之戒。"}},
[375] = {"死亡之寒", {"给布瑞尔的格雷森·戴德马带回5张夜行蝙蝠的毛皮和一些粗线。"}},
[376] = {"被诅咒者", {"新兵艾尔雷斯需要6只食腐狼的爪子和6只夜行蝙蝠翼。"}},
[377] = {"罪与罚", {"夜色镇的米尔斯迪普议员要你杀死迪克斯特·瓦德，并把他的手带回来作为证明。"}},
[378] = {"卡姆·深怒", {"丹莫德的莫特雷·加玛森要求你把卡姆·深怒的头颅交给他。"}},
[379] = {"口渴的比格维兹", {"给加基森的首席工程师沙克斯·比格维兹带去五只废土水袋。"}},
[380] = {"夜行蜘蛛洞穴", {"执行官阿伦要你去杀掉10只小夜行蜘蛛和8只夜行蜘蛛。"}},
[381] = {"血色十字军", {"从血色信徒和血色新兵身上收集12枚血色十字军臂章，把它们交给执行官阿伦。"}},
[382] = {"十字军信使", {"到十字军营地去杀掉信使迈文·考加尔，将你发现的情报交给执行官阿伦。"}},
[383] = {"重要情报", {"把血色十字军文件交给布瑞尔的执行官塞加德。"}},
[384] = {"啤酒烤猪排", {"卡拉诺斯的拉格纳·雷酒需要6块峭壁野猪肋排和1杯狂想麦酒。"}},
[385] = {"捕猎鳄鱼", {"收集5块鳄鱼肉和6张鳄鱼皮，把它们交给旅行者营地里的马雷克·铁心。"}},
[386] = {"伸张正义", {"把塔格尔的头颅带给湖畔镇的卫兵伯尔顿。"}},
[387] = {"镇压暴动", {"暴风城的典狱官塞尔沃特要求你杀死监狱中的10名迪菲亚囚徒、8名迪菲亚罪犯和8名迪菲亚叛军。"}},
[388] = {"鲜血的颜色", {"暴风城的尼科瓦·拉斯克要你取得10条红色毛纺面罩。"}},
[389] = {"巴吉尔·特雷德", {"与监狱的典狱官塞尔沃特谈一谈。"}},
[391] = {"监狱暴动", {"杀死巴基尔·斯瑞德，把他的头带给监狱的典狱官塞尔沃特。"}},
[392] = {"好奇的访客", {"将神秘访客的资料交给暴风城的巴隆斯·阿历克斯顿。"}},
[393] = {"往日的阴影", {"与旧城区的马迪亚斯·肖尔谈一谈。"}},
[394] = {"禽兽的首级", {"去见暴风城旧城区的马迪亚斯·肖尔。"}},
[395] = {"兄弟会的灭亡", {"与暴风城的巴隆斯·阿历克斯顿谈一谈。"}},
[396] = {"觐见国王", {"将有关迪菲亚兄弟会的报告送给暴风要塞里的国王瓦里安·乌瑞恩。"}},
[397] = {"干得好", {"去找黑爪加尔德斯的仆人兹吉谈一谈，并向他索要你的酬劳。"}},
[398] = {"悬赏：蛆眼", {"杀死蛆眼，并将他的爪子交给布瑞尔的执行官塞加德以换取酬劳。"}},
[399] = {"童年的记忆", {"到巴隆斯·阿历克斯顿在西部荒野的房子里去找到他的指南针，并将它带回暴风城的教堂广场交给他。"}},
[400] = {"贝尔丁的工具", {"把贝尔丁的工具交给贝尔丁·钢架。"}},
[401] = {"等待希拉完工", {"稍等片刻，然后再和希拉·沃宁迪交谈。"}},
[403] = {"戒备森严", nil},
