[2282] = {"奥瑟尔伐木场", {"打开卢修斯的箱子，拿到偷窃技能证明物，然后把它归还给湖畔镇的卢修斯。"}},
[2283] = {"搜寻项链", {"在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。"}},
[2284] = {"搜寻项链，再来一次", {"在奥达曼里找寻宝石的线索。"}},
[2298] = {"国王的搜查", {"到暴风城里去找到“剃刀”雷吉克。"}},
[2318] = {"翻译日记", {"在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。"}},
[2338] = {"翻译日记", {"将项链借给加卡尔。作为交换，他将帮你翻译日记。"}},
[2339] = {"寻找宝贝", {"从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。","","红宝石被藏在暗影矮人层层设防的地区。","","黄宝石藏在石腭怪活动地区的一个瓮中。","","蓝宝石在格瑞姆洛克手中，他是石腭怪的领袖。","","能量源可能在奥达曼的某个最强生物的手中。"}},
[2342] = {"寻找宝物", {"从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。"}},
[2359] = {"克拉文之塔", {"偷取迪菲亚塔楼钥匙，进入迪菲亚塔楼，看看暮色森林的箱子里到底有什么东西，然后向暴风城的马迪亚斯·肖尔汇报。"}},
[2360] = {"马迪亚斯和迪菲亚潜行者", {"去西部荒野和密探吉尔妮谈一谈。"}},
[2361] = {"修复项链", nil},
[2378] = {"寻找碎手氏族", {"前往奥格瑞玛，和暗影裂口那的申苏尔谈一谈。"}},
[2381] = {"抢劫海盗", {"把南海宝藏带回给棘齿城的卑鄙的维尼克斯。不要忘了从维尼克斯的机械设备中拿取一份大饼干和潜行者工具，你的任务需要使用这两件东西。","","如果你被任何奇怪的鹦鹉攻击，就对它使用大饼干！"}},
[2383] = {"简易羊皮纸", {"阅读简易羊皮纸，然后和试炼谷的弗郎恩谈一谈。"}},
[2398] = {"失踪的矮人", {"在奥达曼找到巴尔洛戈。"}},
[2399] = {"发芽的树叶", nil},
[2418] = {"能量石", {"给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。"}},
[2438] = {"翡翠摄梦符", {"将翡翠摄梦符交给多兰纳尔的塔隆凯·捷根。"}},
[2439] = {"白金圆盘", {"把你的报酬凭证交给铁炉堡银行的丁尼塔·石衣。"}},
[2440] = {"白金圆盘", {"把报酬凭证交给雷霆崖的本娜·冰蹄。"}},
[2459] = {"噬梦者菲罗斯塔", {"多兰纳尔的塔隆凯·捷根要你杀掉7个瘤背秘法师，并找到遗失的珠宝。"}},
[2478] = {"基本不可能的任务", {"从工头希里克斯那里偷出希里克斯的塔楼钥匙，进入塔楼，然后杀掉两个变异风险投资公司工人、两个风险投资公司巡逻员、两个风险投资公司看守。","","杀掉大工头普兹克·加里维克斯，取了他的首级，然后打开加里维克斯的箱子，拿走赞吉尔的改良药剂。将药剂和加里维克斯的头颅交给奥格瑞玛的申苏尔，等候进一步的指示。"}},
[2479] = {"希诺特的帮助", {"到希尔斯布莱德丘陵的塔伦米尔去，把赞吉尔的药剂样品交给瑟尔格·希诺特。","","要去塔伦米尔，可以搭乘飞艇到幽暗城，然后沿着大路向南穿过银松森林，直到希尔斯布莱德丘陵。跟着路标走！"}},
[2480] = {"希诺特的帮助", {"等待瑟尔格·希诺特完成解药。"}},
[2498] = {"向德纳兰回报", {"雷利亚·绿树要你和奥拉密斯湖的德纳兰谈一谈。"}},
[2499] = {"奥肯斯古尔", {"奥拉密斯湖的德纳兰要你去拿到奥肯斯古尔身上的巨大的瘤。"}},
[2500] = {"荒芜之地的材料", {"从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。"}},
[2518] = {"月神的泪水", {"达纳苏斯月神殿的女祭司艾茉拉让你把萨丝拉的银色丝囊交给她。"}},
[2519] = {"月神殿", {"艾奎恩妮让你和月神殿的女祭司艾茉拉谈一谈。"}},
[2520] = {"萨丝拉的祭品", {"女祭司艾茉拉让你将萨丝拉的银色丝囊放在大殿的喷泉处，然后回去见她。"}},
[2541] = {"沉睡的德鲁伊", {"将一个萨满巫毒符咒交给班奈希尔兽穴的奥本·怒爪。"}},
[2561] = {"利爪德鲁伊", {"奥本·怒爪要求你去杀掉他那失去灵魂的身体，然后对其尸体使用巫毒咒符。"}},
[2581] = {"弯牙土狼的颚骨", {"收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。"}},
[2583] = {"野猪的活力", {"收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。"}},
[2584] = {"野猪之魂", nil},
[2585] = {"决定性的打击", {"收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。"}},
[2601] = {"石化蜥蜴的大脑", {"收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。"}},
[2603] = {"秃鹫的活力", {"收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。"}},
[2605] = {"口渴的地精", {"找到1个饱满的露水腺，把它交给加基森的马林·诺格弗格。"}},
[2606] = {"好味道", {"马林·诺格弗格让你与加基森的斯普琳科谈一谈。"}},
[2607] = {"赞吉尔之触", {"到兵营的地窖里去和道克·米希匹克斯谈一谈。"}},
[2608] = {"赞吉尔之触", {"用/lay指令躺下，接受道克·米希匹克斯的治疗。如果他找不到病因，就找不到治疗的方法。"}},
[2609] = {"赞吉尔之触", {"给道克·米希匹克斯带去一束普通野花、一只铅瓶，一根青铜管，最后还要一卷淡绿色丝线。伊提斯综合症可不会不治而愈，年轻的小姐。"}},
[2621] = {"悔恨的战士", {"与斯通纳德的分队指挥官鲁尔格谈一谈。"}},
[2622] = {"丢失的命令", {"与本戈尔谈一谈。"}},
[2623] = {"沼泽空谈者", {"取回酋长的命令，把它们还给部落英雄的灵魂。"}},
[2641] = {"斯普琳科的秘密佐料", {"加基森的斯普琳科要你去给她找到一颗紫色水生菇。"}},
[2661] = {"给马林的粉末", {"斯普琳科让你把紫色粉末交给加基森的马林·诺格弗格。"}},
[2662] = {"诺格弗格药剂", {"马林·诺格弗格让你在他制成药剂之后再去找他。"}},
[2681] = {"禁锢我们的石头", {"解救九个拉瑟莱克的仆从、三个瑟温妮的仆从、三个奥利斯塔的仆从和三个戈洛尔的仆从。完成任务后，回到部落英雄的灵魂这里。"}},
[2741] = {"超级测蛋器", nil},
[2742] = {"林吉被困住了！", {"护送林吉逃出奎尔丹尼小屋，然后在望海崖找到他藏起来的东西。"}},
[2745] = {"潜入城堡", {"与暴风城堡的泰里恩谈一谈。"}},
[2746] = {"必备物品", {"将3块丝绸和2只克拉拉的新鲜苹果交给暴风城的泰里恩。"}},
[2751] = {"野人装甲", {"将2副青铜花纹护腕、2把青铜巨剑和2只锋利的爪子交给奥格瑞玛的奥罗克·沃姆什。"}},
[2752] = {"铁肩铠", {"将4把青铜战斧和4把青铜战锤交给奥格瑞玛的奥罗克·沃姆什。"}},
[2754] = {"疯狂之角", {"将2只结实的铁锤、2双镀银青铜战靴和2副镀银青铜手套交给奥格瑞玛的奥罗克·沃姆什。"}},
[2755] = {"沃姆什的喜悦", {"观察并学习沃姆什的喜悦之舞。"}},
[2760] = {"秘银会", {"和荆棘谷的加尔文谈一谈。"}},
[2766] = {"寻找OOX-22/FE！", {"把定位器带到深痕谷附近山洞中的奥格索普的导航机器人旁边。"}},
[2767] = {"拯救OOX-22/FE！", {"将OOX-22/FE护送到被遗忘的海岸上的码头，然后向藏宝海湾的奥格索普·奥布诺提斯报告。"}},
[2768] = {"探水棒", {"把探水棒交给加基森的首席工程师沙克斯·比格维兹。"}},
[2769] = {"铜栓兄弟", {"和闪光平原的维兹尔·铜栓谈一谈。"}},
[2770] = {"加兹瑞拉", {"把加兹瑞拉的鳞片交给闪光平原的维兹尔·铜栓。"}},
[2781] = {"通缉：卡利夫·斯科比斯汀", {"将卡利夫·斯科比斯汀的头颅交给加基森的首席工程师沙克斯·比格维兹。"}},
[2782] = {"林吉的秘密", {"奥兰·斯内克威瑟是个学者，她对枯木巨魔很有研究，也许她可以帮你看看这块石板。奥兰就住在幽暗城的魔法区里。"}},
[2783] = {"争论", {"与诅咒之地和悲伤沼泽交界处的部落英雄的灵魂谈一谈。"}},
[2784] = {"失落的荣耀", {"聆听部落英雄的灵魂讲述他的故事。"}},
[2801] = {"悲伤的故事", {"聆听部落英雄的灵魂讲述他的故事。"}},
[2821] = {"质量的保证", {"给羽月要塞的普拉特·马克格鲁比带去10张厚重的雪人皮。"}},
[2822] = {"质量的保证", {"给莫沙彻营地的杉多尔·迅蹄带去十张厚重的雪人皮。"}},
