[2847] = {"蛮皮护甲", {"给羽月要塞的普拉特·马克格鲁比带去10块厚皮。"}},
[2848] = {"蛮皮护肩", {"给羽月要塞的普拉特·马克格鲁带去6片厚重护甲片和1株野葡萄。"}},
