[2858] = {"蛮皮战靴", {"给莫沙彻营地的杉多尔·迅蹄带去2条夜色短裤、2双夜色长靴和2株野葡萄。"}},
[2859] = {"蛮皮护腿", {"给莫沙彻营地的杉多尔·迅蹄带去2顶龟鳞头盔、2副龟鳞护腕和2株野葡萄。"}},
[2860] = {"蛮皮护甲大师", {"将杉多尔的信交给雷霆崖的制皮大师犹纳。"}},
[2861] = {"塔贝萨的任务", {"与尘泥沼泽的塔贝萨谈一谈。"}},
[2862] = {"与豺狼人开战", {"将10份木爪豺狼人的鬃毛交给莫沙彻营地的哈杜肯·迅蹄。"}},
[2863] = {"突然袭击", {"在1个小时内杀死5个木爪突击队员，并向哈杜肯·迅蹄汇报。"}},
[2864] = {"特兰雷克", {"与加基森的特兰雷克谈一谈。"}},
[2865] = {"圣甲虫的壳", {"给加基森的特兰雷克带去5个完整的圣甲虫壳。"}},
[2866] = {"索兰萨尔废墟", {"探索索兰萨尔废墟，并调查纳迦在那个地区的情况。"}},
[2867] = {"返回羽月要塞", {"向羽月要塞的珊蒂斯·羽月汇报你的发现。"}},
[2869] = {"憎世纳迦之战", {"收集10块憎世纳迦的鳞片，把它们交给羽月要塞的拉托尼库斯·月矛。"}},
[2870] = {"击败沙尔扎鲁", {"消灭沙尔扎鲁，然后把神秘遗物交给羽月要塞的拉托尼库斯·月矛。"}},
[2871] = {"递送遗物", {"将神秘遗物交给羽月要塞的维斯提亚·月矛。"}},
[2872] = {"斯杜雷的债务", {"与热砂港的斯杜雷谈一谈。"}},
[2873] = {"斯杜雷的货物", {"将斯杜雷的货物交给热砂港的斯杜雷。"}},
[2874] = {"给马克基雷的货物", {"将斯杜雷的瓶子交给藏宝海湾的“海狼”马克基雷。"}},
[2875] = {"通缉：安德雷·费尔比德", {"将安德雷的头颅交给热砂港的安全主管吉罗姆·比格维兹。"}},
[2876] = {"船运时刻表", {"把船运时刻表交给热砂港的某个官员。"}},
