[2881] = {"巨魔部族项链", nil},
[2902] = {"调查木爪岭", {"在莫沙彻营地以南的豺狼人营地中寻找豺狼人的战斗计划。"}},
[2903] = {"作战计划", {"把木爪豺狼人的作战计划交给莫沙彻营地的哈杜肯·迅蹄。"}},
[2904] = {"一团混乱", {"将克努比护送到出口，然后向藏宝海湾的斯库提汇报。"}},
[2922] = {"拯救尖端机器人！", {"将尖端机器人的存储器核心交给铁炉堡的工匠大师欧沃斯巴克。"}},
[2923] = {"工匠大师欧沃斯巴克", {"与铁炉堡的工匠大师欧沃斯巴克谈一谈。"}},
[2924] = {"基础模组", {"收集12个基础模组，把它们交给铁炉堡的科劳莫特·钢尺。"}},
[2925] = {"帮助科劳莫特", {"与铁炉堡的科劳莫特·钢尺谈一谈。"}},
[2926] = {"诺恩", {"用空铅瓶对着辐射入侵者或者辐射抢劫者，从它们身上收集放射尘。瓶子装满之后，把它交给卡拉诺斯的奥齐·电环。"}},
[2927] = {"灾难之后", {"与卡拉诺斯的奥齐·电环谈一谈。"}},
[2928] = {"陀螺式挖掘机", {"收集24副机械内胆，把它们交给暴风城的舒尼。"}},
[2929] = {"大叛徒", {"到诺莫瑞根去杀掉机械师瑟玛普拉格。完成任务之后向大工匠梅卡托克报告。"}},
[2930] = {"抢救数据", {"将彩色穿孔卡片交给铁炉堡的大机械师卡斯派普。"}},
[2931] = {"卡斯派普的任务", {"与铁炉堡的大机械师卡斯派普谈一谈。"}},
[2932] = {"可怕的消息", {"在辛特兰收集枯木巨魔的头皮，把它们串在尼姆布亚之矛上。将尼姆布亚的长矛插在辛特兰的某个枯木巨魔村庄中，然后回到荆棘谷的尼姆布亚那里。"}},
