[3517] = {"偷窃知识", nil},
[3519] = {"需要帮助的朋友", {"与幽影谷的迪兰妮亚·银辉谈一谈。"}},
[3520] = {"尖啸者的灵魂", {"在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。"}},
[3521] = {"埃沃隆的解药", {"在幽影谷中为迪兰妮亚·银辉收集7朵紫蓝色蘑菇、4朵月牙百合花和一份树林蜘蛛的脓液。"}},
[3522] = {"埃沃隆的解药", {"在5分钟内将埃沃隆的解药交给他。你可以北边的洞穴入口外面找到埃沃隆。"}},
[3523] = {"剃刀高地的亡灵天灾", {"如果你同意帮助奔尼斯特拉兹，就再跟他谈谈，并将誓言石还给他。"}},
[3524] = {"搁浅的巨兽", {"从奥伯丁南面的海岸上收集海洋生物的骨头，然后带着骨头向奥伯丁的温尼斯·布莱葛回复。"}},
[3525] = {"封印神像", {"保护奔尼斯特拉兹来到剃刀高地的野猪人神像处。","","当他在进行仪式封印神像时保护他。"}},
[3527] = {"摩沙鲁的预言", {"将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。"}},
[3528] = {"神灵哈卡", {"将装满的哈卡之卵交给塔纳利斯的叶基亚。"}},
[3568] = {"堕落之水", {"在艾萨拉的埃达拉斯废墟旁的海潮之池中收集4瓶水，然后回到药剂师科雷那儿。"}},
[3601] = {"我就是基姆加尔！", {"搜索萨拉斯营地，找到基姆加尔的指南针、望远镜、烧鸡和花生，然后把它们交给艾萨拉的基姆加尔。"}},
[3632] = {"侏儒工程学", nil},
[3636] = {"与圣光同在", {"大主教本尼迪塔斯要你去杀死剃刀高地的寒冰之王亚门纳尔。"}},
[3661] = {"月神之兽？", {"为鲁瑟兰村的艾瑞拉斯·琥珀收集15支枭兽羽毛。"}},
[3701] = {"索瑞森废墟", {"到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。"}},
[3702] = {"索瑞森废墟", {"听皇家历史学家阿克瑟努斯讲述索瑞森的历史。"}},
[3741] = {"希拉里的项链", {"找到希拉里的项链，将其还给湖畔镇的希拉里。"}},
[3761] = {"安戈洛的泥土", {"收集20份安戈洛的泥土，把它们交给雷霆崖的格德。"}},
[3764] = {"安戈洛的泥土", {"收集20份安戈洛的泥土，把它们交给达纳苏斯的耶纳尔。"}},
[3765] = {"遥远的旅途", {"到奥伯丁的戈沙拉·夜语那儿去。"}},
[3781] = {"晨光麦研究", {"将大德鲁伊的草种购买券交给达纳苏斯城塞纳里奥区的玛斯雷·驭熊者。"}},
[3783] = {"雪怪计划！", {"为永望镇的乌米收集10张厚雪人毛皮。"}},
[3785] = {"晨光麦研究", {"用一个常青袋、一包萨伦迪斯种子以及两份安戈洛的泥土来尝试种植晨光麦。","","将10株晨光麦交给达纳苏斯的玛斯雷·驭熊者。"}},
[3788] = {"奎恩提斯的请求", {"与羽月要塞的奎恩提斯谈一谈。"}},
[3789] = {"协助大德鲁伊", {"与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。"}},
[3790] = {"协助大德鲁伊", {"与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。"}},
[3791] = {"晨光麦的秘密", {"将10株晨光麦交给羽月要塞的奎恩提斯。"}},
[3792] = {"羽月要塞的晨光麦", nil},
[3801] = {"黑铁的遗产", {"如果你想要得到进入这座城市主城区的钥匙，就去和弗兰克罗恩·铸铁谈一谈。"}},
[3802] = {"黑铁的遗产", {"杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。"}},
[3821] = {"巨槌石", {"到燃烧平原去找到沙妮·长齿。"}},
[3822] = {"克罗格鲁尔", {"从克罗格鲁尔手中拿回沙妮的鼻环，把它还给卡加斯的萨特拉克。搜寻巨槌石的每一处山洞和矿井。"}},
[3823] = {"消灭火腹食人魔", {"杀掉15个火腹食人魔法师、7个火腹食人魔和7个火腹蛮兵，完成任务之后向奥拉留斯报告。"}},
[3824] = {"蛮王戈泰什", {"找到戈泰什，他应该在巨槌石西面的某处。杀掉戈泰什并把他的头颅交给燃烧平原的奥拉留斯。"}},
[3844] = {"无人知晓的秘密", {"在池塘附近查找与搁浅的小艇有关的线索。"}},
[3845] = {"无人知晓的秘密", {"查看袋子里的东西，然后将它们交给物主。"}},
[3861] = {"咕咕嘎！", {"找一些特殊的鸡饲料，把它交给友好的小鸡。当你找到小鸡的时候，在喂食它之前对它做出高兴的表情。（使用/cheer命令）"}},
[3881] = {"抢救物资", {"将食物箱和研究设备交给安戈洛环形山的威利德·马绍尔。"}},
[3882] = {"挖骨头", {"将8根恐龙骨头交给安戈洛环形山的斯巴克·尼米尔。"}},
[3883] = {"异型的生态", {"使用采集瓶从安戈洛环形山的某个格里什虫巢的孵化室中收集一份巢穴侧壁的样本，在有悬挂着的虫卵的房间里收集样本。","","将虫穴内壁样本交给安戈洛环形山的霍莱伊·马绍尔。"}},
[3884] = {"威利德的日记", {"将日记还给安戈洛环形山中的威利德·马绍尔。"}},
[3901] = {"断骨骷髅", {"杀掉12个断骨骷髅，然后回到丧钟镇的暗影牧师萨维斯那里。"}},
[3902] = {"捡破烂", {"在丧钟镇及临近地区搜寻6件破烂装备，把它们交给亡灵卫兵萨尔坦。"}},
[3903] = {"米莉·奥斯沃斯", {"与米莉·奥斯沃斯谈一谈。"}},
[3904] = {"米莉的葡萄", {"收集8箱米莉的葡萄，把它们交给北郡修道院的米莉·奥斯沃斯。"}},
[3905] = {"葡萄出货单", {"将葡萄出货单交给北郡修道院的尼尔斯修士。"}},
[3906] = {"不和谐的烈焰", {"到黑石山脉的采石场去干掉征服者派隆，然后向桑德哈特回报。"}},
[3907] = {"不和谐的火焰", {"进入黑石深渊并找到伊森迪奥斯。杀掉它，然后把你找到的信息汇报给桑德哈特。"}},
[3908] = {"无人知晓的秘密", {"把林克的剑交给冬泉谷的多诺瓦·雪山。"}},
[3909] = {"视灵药剂", {"去菲拉斯找格雷甘·山酒。从他那里问到获取视灵药剂的方法，然后向冬泉谷的多诺瓦·雪山复命。"}},
[3912] = {"墓地相见", {"在加基森镇外的墓地中使用视灵药剂，然后按照多诺瓦的指示找到加里杨。"}},
[3913] = {"寻找墓碑", {"复活，然后寻找加里杨让你去找的那块墓碑。"}},
[3914] = {"林克的剑", {"把林克的强化之剑交给安戈洛尔环形山的林克。"}},
[3921] = {"维妮·布特巴克", {"将损坏的主动式负载平衡器交给维妮·布特巴克。"}},
[3922] = {"高强度齿轮", {"把15个高强度齿轮交给贫瘠之地的维妮·布特巴克。"}},
[3923] = {"雷里·格里斯高布", {"把破碎的主动式负载平衡器交给奥格瑞玛的雷里·格里斯高布。"}},
[3924] = {"主动式负载平衡器说明书", {"把主动式负载平衡器说明书交给奥格瑞玛的雷里·格里斯高布。"}},
[3941] = {"侏儒的援助", {"到马绍尔营地那里的山洞中去找科琳。"}},
[3942] = {"林克的记忆", {"到费伍德森林去找艾瑞丹·蓝风。"}},
[3961] = {"林克的冒险", {"把亚奎门塔斯的银图腾交给马绍尔营地里的林克。"}},
[3962] = {"结伴而行", {"到马绍尔营地南边的火羽山去。","","找到火焰使者，并使用图腾除掉它的防护光环。在击败它之后从洞中取得金色火焰。"}},
[3981] = {"指挥官哥沙克", {"在黑石深渊里找到指挥官哥沙克。","","在那幅草图上画着的是一个铁栏后面的兽人，也许你应该到某个类似监狱的地方去找找看。"}},
[3982] = {"出了什么事？", {"保护哥沙克。"}},
[4001] = {"出了什么事？", {"与卡兰·巨锤谈一谈，收集关于绑架公主铁炉堡公主茉艾拉·铜须这一事件的情报。将情报反馈给奥格瑞玛城里的萨尔。","","哥沙克提到过卡兰被关在附近的某个牢房中。"}},
[4002] = {"东部王国", {"如果你准备好要接受萨尔所安排的任务，就去找他谈一谈。"}},
[4003] = {"拯救公主", {"杀掉达格兰·索瑞森大帝，然后将铁炉堡公主茉艾拉·铜须从他的邪恶诅咒中拯救出来。"}},
[4004] = {"拯救公主？", {"向萨尔报告！"}},
[4005] = {"亚奎门塔斯", {"把阿奎尔之书、银爪和铁树之心带到塔纳利斯去。","","使用这本书召唤亚奎门塔斯。","","在图腾完成之后，把它交给马绍尔营地的科琳。"}},
[4021] = {"人马无双！", {"将克罗姆扎军旗的碎片交给十字路口西边的雷戈萨·死门。"}},
[4022] = {"烈焰精华", {"向塞勒斯·萨雷芬图斯展示你从威拉罗克·温布雷那里得到的黑龙皮。"}},
[4023] = {"烈焰精华", {"向塞勒斯·萨雷芬图斯证明你的价值。","","你感觉到塞勒斯似乎对你不屑一顾。"}},
[4024] = {"烈焰精华", {"到黑石深渊去杀掉贝尔加。","","你只知道这个巨型怪物住在黑石深渊的最深处。记住你要使用特殊的黑龙皮从贝尔加的尸体上采集烈焰精华。","","将你采集到的烈焰精华交给塞勒斯·萨雷芬图斯。"}},
[4041] = {"视灵药剂", nil},
[4061] = {"机器的崛起", {"到燃烧平原去为塞朵拉·穆瓦丹尼收集10块断裂的元素碎片。","","塞朵拉曾经说过，那里的机械傀儡和元素生物是这种碎片的主要来源。"}},
[4062] = {"机器的崛起", {"将元素碎片样本交给鲁特维尔·沃拉图斯。","","塞朵拉说鲁特维尔就在东边的一处营地里。"}},
[4063] = {"机器的崛起", {"找到并杀掉傀儡统帅阿格曼奇，将他的头交给鲁特维尔。你还需要从守卫着阿格曼奇的狂怒傀儡和战斗傀儡身上收集10块完整的元素核心。"}},
[4081] = {"格杀勿论：黑铁矮人", {"到黑石深渊去消灭那些邪恶的侵略者！","","军官高图斯要你去杀死15个铁怒卫士、10个铁怒狱卒和5个铁怒步兵。完成任务之后回去向他复命。"}},
[4082] = {"格杀勿论：高阶黑铁军官", {"到黑石深渊去消灭那些邪恶的侵略者！","","高图斯军阀要你杀死10个铁怒医师,、10个铁怒士兵和10个铁怒军官。完成任务之后回去向他复命。"}},
[4084] = {"银爪铁心", {"为费伍德森林的艾瑞丹·蓝风收集11只银爪和1颗铁树之心。"}},
[4101] = {"净化费伍德", {"收集15颗血琥珀，把它们交给费伍德森林的阿拉珊蒂丝·银空。"}},
[4113] = {"被腐化的轻歌花", nil},
[4118] = {"被腐化的轻歌花", nil},
[4120] = {"堕落的力量", {"菲拉斯莫沙彻营地的塔罗·刺蹄要你去费伍德森林杀掉12头怒爪灰熊和12头魔爪掠夺者。"}},
[4121] = {"押送囚徒", {"押送你的囚犯格拉克·洛克鲁布。穿过燃烧平原和黑石山脉，一直走到灼热峡谷。","","雷克斯洛特曾经告诉过你，他会让他的人等在黑石山脉的另外一边准备接收格拉克。","","另外，你还要把瑟银镣铐一并还给雷克斯洛特。"}},
[4122] = {"格拉克·洛克鲁布", {"到燃烧平原去找到格拉克·洛克鲁布。你回忆起雷克斯洛特曾经提起过，格拉克应该是在一座大型的黑石要塞中。","","当你找到格拉克·洛克鲁布之后，用瑟银镣铐把他铐起来，然后将其带回灼热峡谷。雷克斯洛特会让他的部下等在那里接应你。"}},
[4123] = {"山脉之心", {"把山脉之心交给燃烧平原的麦克斯沃特·尤博格林。"}},
[4124] = {"失踪的信使", {"和羽月要塞的基恩诺·火花谈一谈。"}},
[4125] = {"失踪的信使", {"找到信使的小船，你应该在菲拉斯的南部海岸线上展开搜索。"}},
[4126] = {"霍尔雷·黑须", {"把遗失的雷酒秘方带给卡拉诺斯的拉格纳·雷酒。"}},
[4127] = {"船只的残骸", {"回到羽月要塞，给基恩诺·火花看看你找到的这把被丢弃的小刀。"}},
[4128] = {"拉格纳·雷酒", {"和拉格纳·雷酒谈一谈。"}},
[4129] = {"奎恩提斯的技艺", {"把被丢弃的小刀交给羽月要塞的奎恩提斯。"}},
[4130] = {"心灵占卜术", {"和羽月要塞的基恩诺·火花谈一谈。"}},
[4131] = {"木爪豺狼人", {"在菲拉斯南部地区的木爪豺狼人营地里寻找信使的下落或者信使的物品。"}},
[4133] = {"薇薇安·拉格雷", {"与卡加斯的暗法师薇薇安·拉格雷谈一谈。"}},
[4134] = {"遗失的雷酒秘方", {"把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。"}},
[4135] = {"痛苦深渊", {"现在你已经知道了拉斯卡尔的去向，那么你最好到痛苦深渊去寻找他，或者至少是他的尸体。根据便笺上的信息，那个地方应该在木爪豺狼人营地的南边。"}},
[4136] = {"雷布里·斯库比格特", {"把雷布里的头颅交给燃烧平原的尤卡·斯库比格特。"}},
[4141] = {"穆尔金和拉瑞安", {"从安戈洛尔环形山的血瓣花猛击者和血瓣花掠夺者身上收集15个血瓣花，然后向穆尔金回复。"}},
[4142] = {"造访格雷甘", {"把血瓣花交给菲拉斯的格雷甘·山酒。"}},
[4143] = {"邪恶之雾", {"收集5份阿塔莱之雾的样本，然后向安戈洛环形山的穆尔金复命。"}},
[4144] = {"血瓣花苗", nil},
[4161] = {"卡多雷的菜谱", {"为多兰纳尔的扎瑞恩收集7条小蜘蛛腿。"}},
[4181] = {"地精工程学", {"如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。"}},
[4182] = {"黑龙的威胁", {"杀掉15条黑色小龙、10条黑色龙兽和1条黑色幼龙。当你完成任务之后就向赫林迪斯·河角回报。"}},
[4183] = {"真正的主人", {"把赫林迪斯·河角的信交给湖畔镇的所罗门镇长。"}},
[4184] = {"真正的主人", {"到暴风城去把所罗门的求援信交给伯瓦尔·弗塔根公爵。","","伯瓦尔在暴风要塞里。"}},
[4185] = {"真正的主人", {"与女伯爵卡特拉娜·普瑞斯托谈话，然后再与伯瓦尔·弗塔根公爵谈话。"}},
[4186] = {"真正的主人", {"把伯瓦尔的命令交给湖畔镇的所罗门镇长。"}},
[4201] = {"爱情药水", {"将4份格罗姆之血、10块巨型银矿和装满水的娜玛拉之瓶交给黑石深渊的娜玛拉小姐。"}},
[4223] = {"真正的主人", {"和燃烧平原的麦克斯韦尔元帅谈一谈。"}},
[4224] = {"真正的主人", {"和狼狈不堪的约翰谈谈来了解温德索尔元帅的命运，然后回到麦克斯韦尔元帅那里。","","你想起麦克斯韦尔元帅说过他在一个北面的洞穴那里。"}},
[4241] = {"温德索尔元帅", {"到西北部的黑石山脉去，在黑石深渊中找到温德索尔元帅的下落。","","狼狈不堪的约翰曾告诉你说温德索尔被关进了一个监狱。"}},
[4243] = {"找回A-Me 01", {"在安戈洛环形山找到A-Me 01。"}},
[4244] = {"找回A-Me 01", {"找到一个秘银外壳，然后回到安戈洛环形山的A-Me 01身边。"}},
[4245] = {"找回A-Me 01", {"将A-Me 01交给安戈洛环形山的卡尔纳·雷塔维。"}},
[4261] = {"远古之灵", {"护送艾雷到灰谷，然后和灰谷东部的林歌神殿中的凯尼斯·静风谈一谈。"}},
[4262] = {"征服者派隆", {"杀掉征服者派隆，然后向加琳达复命。","","加琳达告诉过你，派隆守在采矿场中，也许你应该去那里找找。"}},
[4265] = {"逃离虫巢", {"将拉斯卡尔安全护送到祖卡什虫巢外。","","回到羽月要塞的基恩诺·火花那儿，告诉他拉斯卡尔还活着，且状况良好。"}},
[4266] = {"羽月将军的欢迎", {"与羽月要塞的珊蒂斯·羽月谈一谈。"}},
[4267] = {"异种蝎的崛起", {"把拉斯卡尔的报告交给达纳苏斯的格拉希娜·灵风。"}},
[4281] = {"萨兰纳尔的货物", {"将未递送的包裹交给萨兰纳尔驿站的法芬德尔。"}},
[4283] = {"五十个！", {"奥拉留斯想要50枚黑石徽章。在燃烧平原的兽人身上应该可以找到那些徽章。"}},
[4284] = {"能量水晶", {"收集红色能量水晶、蓝色能量水晶、黄色能量水晶和绿色能量水晶各7块，把它们交给马绍尔营地里的科琳。"}},
[4285] = {"北部水晶塔", {"在安戈洛尔环形山找到北部水晶塔。"}},
[4286] = {"好东西", {"到黑石深渊去找到20个黑铁挎包。当你完成任务之后，回到奥拉留斯那里复命。你认为黑石深渊里的黑铁矮人应该会有这些黑铁挎包。"}},
[4287] = {"东部水晶塔", {"在安戈洛尔环形山找到东部水晶塔。"}},
[4288] = {"西部水晶塔", {"在安戈洛尔环形山找到西部水晶塔。"}},
[4289] = {"安戈洛的猩猩", {"将2块安戈洛猩猩的皮、2块安戈洛大猩猩的皮和2块安戈洛巨猩猩的皮交给安戈洛环形山入口处的托尔瓦·寻路者。"}},
[4290] = {"拉克维的食物", {"找到拉克维刚刚猎杀的动物的尸体，从尸体上偷取一块蛇颈龙肉块，然后回到安戈洛环形山的托尔瓦·寻路者那里。"}},
[4291] = {"拉克维的气味", {"将2份暴掠龙信息素交给安戈洛尔环形山入口附近的托尔瓦·寻路者。"}},
[4292] = {"拉克维的诱饵", {"使用托尔瓦的麻袋中的东西召唤拉克维并打败它。将拉克维的头颅交给安戈洛环形山入口处的托尔瓦·寻路者。"}},
[4293] = {"软泥怪的样本…", {"从费伍德的软泥怪身上收集费伍德软泥怪样本，然后使用幽暗城的化学家弗雷身旁的测试设备来检测你所收集的样本中哪一份被腐化的程度最深。给化学家弗雷带去5个被腐化的费伍德样本。"}},
[4294] = {"一大堆软泥怪", {"从安戈洛尔环形山那里任何泥浆怪身上收集安戈洛泥浆怪样本。使用幽暗城的化学家弗雷身旁的测试仪器来检验你所采集到的样本的纯度。把5份纯净的安戈洛样本送到化学家弗雷那里去。"}},
[4296] = {"七贤石板", {"把石板拓文交给燃烧平原的麦克斯沃特·尤博格林。"}},
[4300] = {"骨刃武器", {"将8只白色暴掠龙爪交给奥格瑞玛的杰斯雷蒙。"}},
[4301] = {"强大的尤尔查", {"把尤尔查的毛皮交给安戈洛环形山入口处的托尔瓦·寻路者。"}},
[4321] = {"分析水晶塔", {"过一会再和科琳说话。"}},
[4324] = {"尤卡·斯库比格特", {"与燃烧平原的尤卡·斯库比格特谈一谈。"}},
[4341] = {"卡兰·巨锤", nil},
[4402] = {"戈加尔的清凉果", {"收集10个仙人掌果，把它们交给戈加尔。你记得他说可以在仙人掌上收集到这种果子。"}},
[4403] = {"被腐化的迎风花", nil},
[4421] = {"碧火萨特", {"杀掉11个碧火魔仆、9个碧火巡影者、9个碧火潜行者和萨瓦瑟拉斯。任务完成之后回到费伍德森林的艾瑞丹·蓝风处复命。"}},
[4441] = {"被禁锢的古树", {"到达纳苏斯去，用艾瑞丹的瓶子收集月神殿中的祝福之水，然后回到艾瑞丹那儿。"}},
[4442] = {"净化！", {"过一会儿再与艾瑞丹对话。"}},
[4449] = {"被锁起来的矮人", {"杀掉8个黑铁地质学家，并将15块丝绸交给灼热峡谷里那个被锁在厕所中的矮人。"}},
[4450] = {"塔纳利斯的账本", {"把古德斯迪尔的账本和上面所列的物品交给塔纳利斯的克林科·古德斯迪尔。"}},
[4451] = {"自由的钥匙", {"搜寻灼热峡谷并找到一个可以插入这把格里塞特厕所钥匙的锁眼。"}},
[4467] = {"被腐化的迎风花", nil},
[4488] = {"召唤地狱战马", {"与棘齿城的斯坦哈德·法尔杉谈一谈。"}},
[4489] = {"召唤地狱战马", {"与棘齿城的斯坦哈德·法尔杉谈一谈。"}},
[4490] = {"召唤地狱战马", {"与棘齿城的斯坦哈德·法尔杉谈一谈，学习召唤地狱战马的能力。"}},
[4491] = {"朋友的帮助", {"把林格带回马绍尔营地的斯普拉格·弗劳克身边。","","如果林格晕倒了，就用斯普拉格的水壶让他恢复。"}},
[4492] = {"走丢了！", {"在火羽山找到林格。"}},
[4494] = {"异种蝎的远征", {"与加基森的炼金师匹斯特苏格谈一谈。"}},
[4495] = {"好朋友", {"在北边的洞穴附近找到埃沃隆。"}},
[4496] = {"擒虫先擒王", {"把一份格里什信息素和5份安戈洛的泥土样本交给加基森的炼金师匹斯特苏格。"}},
[4501] = {"当心翼手龙", {"杀掉10只翼手龙和15只狂怒的翼手龙，然后向马绍尔营地的斯普拉格·弗劳克报告。"}},
[4502] = {"火山的活动", {"到安戈洛环形山的火山中去，从那里的元素身上收集9份安戈洛灰烬，把它们交给棘齿城的莉芙·雷兹菲克斯。"}},
[4503] = {"希兹尔的的飞行器", {"为马绍尔营地的希兹尔收集8块精细的双帆龙鳞片和8块精细的翼手龙鳞片。"}},
[4504] = {"极度粘稠的沥青", {"帮加基森的特兰雷克收集12块极度粘稠的沥青。"}},
[4507] = {"捕捉皇后", {"召唤格里什皇后，然后击败她。","","把格里什皇后的大脑交给加基森的炼金师匹斯特苏格。"}},
[4508] = {"临危不惧", {"把匹斯特苏格的安戈洛报告交给达纳苏斯的格拉希娜·灵风。"}},
[4510] = {"临危不惧", {"把银行赠券交给达纳苏斯银行的伊迪瑞娜。"}},
[4512] = {"远方的软泥怪", {"将6瓶被诅咒的软泥怪样本和6瓶被污染的软泥怪样本交给铁炉堡的拉里斯·空轮。"}},
[4513] = {"远方的软泥怪", {"将10个纯净样本瓶交给铁炉堡的拉里斯·空轮。","","如果你无法找到它们的话，不妨到拉里斯那里去再打听一些线索。"}},
[4542] = {"给乱风岗的紧急信件", {"把紧急信件交给乱风岗的峭壁卫兵图林·长角。"}},
[4581] = {"凯尼斯·静风", {"把辛德瑞尔的便笺交给林歌神殿里的凯尼斯·静风。"}},
[4601] = {"超级清洁器5200型！", {"将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。"}},
