[5046] = {"野猪之皮", nil},
[5048] = {"善良的艾玛", {"找到暴风城的艾玛并弄清她是否就是艾玛·费尔斯通。如果是的话，那么她可能想要拿到詹妮丝·费尔斯通给她的包裹。"}},
[5050] = {"好运护符", {"把半个好运护符还给西瘟疫之地的詹妮丝·费尔斯通。"}},
[5051] = {"两半合一", {"在西瘟疫之地的费尔斯通农场某地找到另外一半好运护符，并把两半护符合并。","","把好运护符交给西瘟疫之地费尔斯通农场的詹妮丝·费尔斯通。"}},
[5052] = {"阿迦玛甘的血岩碎片", {"给陶拉祖营地的碎牙带去一块血岩碎片。","","如果你想要他赐予你阿迦玛甘的力量，就搜集更多的血岩碎片。"}},
[5058] = {"达尔松夫人的日记", nil},
[5059] = {"被锁起来的农夫", nil},
[5060] = {"被锁起来的农夫", nil},
[5061] = {"水栖形态", {"回到达纳苏斯，让玛斯雷·驭熊者看看你的海狮坠饰。"}},
[5062] = {"神圣之火", {"收集10支火岩龙舌兰，然后去找雷霆崖长者高地的玛加萨·恐怖图腾。"}},
[5064] = {"恐怖图腾的密信", {"在黑云峰拿到三封密信。"}},
[5065] = {"失落的摩沙鲁石板", {"把第三块和第四块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。"}},
[5066] = {"战斗的号角：瘟疫之地！", {"找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。"}},
[5082] = {"冬泉熊怪的威胁", {"冬泉谷的多诺瓦·雪山要你去杀死8个冬泉探路者、8个冬泉巢穴守卫和8个冬泉图腾师。"}},
[5088] = {"阿利卡拉", {"消灭阿利卡拉。把她的遗体和火岩粉交给白沙岗哨的莫特加·火鬃作为证明。"}},
[5090] = {"战斗的号角：瘟疫之地！", {"找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。"}},
[5091] = {"战斗的号角：瘟疫之地！", {"找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。"}},
[5092] = {"扫清道路", {"杀掉悔恨岭中的10个骷髅剥皮者和10个被奴役的食尸鬼。","","然后向西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特复命。"}},
[5093] = {"战斗的号角：瘟疫之地！", {"找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。"}},
[5096] = {"误导血色十字军", {"到血色十字军建在费尔斯通农场和达尔松之泪之间的营地去，摧毁他们的指挥帐篷。","","将亡灵天灾的战旗插在营地中，然后回到西瘟疫之地亡灵壁垒的高级执行官德灵顿那儿。"}},
[5097] = {"标记哨塔", {"使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。","","在做完了标记之后，将信号火炬还给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。"}},
[5142] = {"小帕米拉", {"找到帕米拉·雷德帕斯。"}},
[5147] = {"通缉：阿纳克·恐怖图腾", {"杀死阿纳克·恐怖图腾，并向乱风岗的峭壁卫兵图林·长角出示证据。"}},
[5148] = {"部族制皮", {"将1件蛮皮外衣和1件蛮皮头盔交给荆棘谷的瑟伊布。","","完成这项任务之后，你就可以学到部族制皮技术了。","","同时，你也将永远无法学习元素制皮技术和龙鳞制皮技术，在决定之前先考虑清楚。"}},
[5150] = {"达丹加饿了！", nil},
[5151] = {"超适应齿轮", {"杀了那头野兽，把超适应齿轮和钥匙交给维兹罗。"}},
[5152] = {"玛莱恩姑妈", {"与安多哈尔废墟南边的玛莱恩谈一谈。"}},
[5155] = {"加德纳尔的势力", {"到加德纳尔去杀掉4个加德纳尔恶犬、4个加德纳尔守护者、6个加德纳尔精兵和6个加德纳尔祭司，然后向费伍德森林的格雷塔·苔蹄复命。"}},
[5156] = {"验证腐蚀", {"杀掉2个热能野兽和2个热能恐兽，并探索碎痕谷。然后查看凹坑中是否仍然充满了堕落的恶臭之水，完成这些任务之后，向费伍德森林中的塔诺恩·红羽复命。"}},
[5157] = {"收集堕落之水", {"把空壶拿到加德纳尔中心的月亮井去，装满井水之后再回到费伍德森林的格雷塔·苔蹄那里。"}},
[5158] = {"水之魂的帮助", {"把腐化的月亮井水交给贫瘠之地的水之先知伊斯伦。"}},
[5159] = {"净化过的水", {"把净化过的月亮井水交给费伍德森林的格雷塔·苔蹄。"}},
[5165] = {"熄灭火焰", nil},
[5211] = {"达隆郡的保卫者", {"释放15个达隆郡居民的灵魂，然后返回卡林·雷德帕斯身边。"}},
[5215] = {"瘟疫之锅", {"与西瘟疫之地冰风岗的高阶牧师玛多妮尔谈一谈。"}},
[5216] = {"目标：费尔斯通农场", {"到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。"}},
[5217] = {"返回冰风岗", {"把费尔斯通农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"}},
[5219] = {"目标：达尔松之泪", {"到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。"}},
[5220] = {"返回冰风岗", {"把达尔松之泪的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"}},
[5222] = {"目标：嚎哭鬼屋", {"到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。"}},
[5223] = {"返回冰风岗", {"把嚎哭鬼屋的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"}},
[5225] = {"目标：盖罗恩农场", {"到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。"}},
[5226] = {"返回冰风岗", {"把盖罗恩农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。"}},
