[5623] = {"圣光的恩赐", {"与艾尔文森林的女牧师洁塞塔谈一谈。"}},
[5624] = {"圣光之衣", {"找到卫兵罗伯兹并使用次级治疗术（等级 2）来治疗他。然后对他施放真言术：韧，最后向闪金镇的女牧师洁塞塔复命。"}},
[5625] = {"圣光之衣", {"找到巡山人多尔夫并使用次级治疗术（等级 2）来治疗他。然后对他施放真言术：韧，最后向卡拉诺斯的马克萨恩·安沃尔复命。"}},
