[5741] = {"圣光节杖", {"拿到圣光节杖，并将它交给艾瑟雷索塔里的阿佐尔·奥达蒙特。"}},
[5761] = {"饥饿者塔拉加曼", {"进入怒焰裂谷，杀死饥饿者塔拉加曼，然后把他的心脏交给奥格瑞玛的尼尔鲁·火刃。"}},
[5762] = {"赫米特·奈辛瓦里", {"将克拉维尔的箱子送到荆棘谷的赫米特·奈辛瓦里那里。"}},
[5763] = {"荆棘谷狩猎", {"将鲁恩的科多兽角送到荆棘谷的赫米特·奈辛瓦里那里。"}},
[5821] = {"雇佣保镖", {"护送基泽尔顿商队通过科卡尔半人马村，然后与瑟卡布斯库的营地中的斯米德谈话以领取你的奖赏。"}},
[5848] = {"爱与家庭", {"到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到“爱与家庭”这幅画，它被隐藏在另一幅描绘两个月亮的画之后。","","把这幅画还给提里奥·弗丁。"}},
[5863] = {"砂槌食人魔", {"加基森的安迪·利恩想要你攻入砂槌营地，杀死10个砂槌蛮兵、10个砂槌执行者，以及掠夺者格玛洛克。"}},
[5881] = {"召回卫兵", {"马格兰希望你将信送到贫瘠之地升降梯的瑞什·远行者手中。"}},
[5882] = {"狩猎换药膏", nil},
[5901] = {"瘟疫与你", {"在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到提瑞斯法林地的亡灵壁垒去找米克·莱文。"}},
[5903] = {"瘟疫与你", {"在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到西瘟疫之地的冰风岗去找纳萨尼尔·杜马。"}},
[5921] = {"月光林地", {"使用法术“传送：月光林地”抵达月光林地，在那里与永夜港的德迪利特·星焰谈一谈。"}},
[5922] = {"月光林地", {"使用法术“传送：月光林地”抵达月光林地，在那里与永夜港的德迪利特·星焰谈一谈。"}},
[5923] = {"响应召唤", {"与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。"}},
[5925] = {"响应召唤", {"与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。"}},
[5928] = {"响应召唤", {"与雷霆崖长者高地上的图拉克·符文图腾谈一谈。"}},
[5929] = {"巨熊之灵", {"到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。"}},
[5930] = {"巨熊之灵", {"到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。"}},
[5931] = {"返回达纳苏斯", {"回到达纳苏斯，与塞纳里奥区的玛斯雷·驭熊者谈一谈。"}},
[5932] = {"返回雷霆崖", {"回到雷霆崖，与长者高地的图拉克·符文图腾谈一谈。"}},
[6001] = {"身心之力", {"使用奥伯丁的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。","","任务完成之后，与达纳苏斯的玛斯雷·驭熊者谈一谈。"}},
[6002] = {"身心之力", {"使用莫高雷与贫瘠之地交界处的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。","","任务完成之后，与雷霆崖的图拉克·符文图腾谈一谈。"}},
[6004] = {"未竟的事业", {"杀死2个血色医护员、2个血色猎人、2个血色魔法师和2个血色骑士，然后回到西瘟疫之地的科尔斯塔·迪普沙东那儿。"}},
[6021] = {"流亡者塞达尔", {"将塞达尔的头颅交给圣光之愿礼拜堂的护理者奥林。"}},
[6023] = {"未完的任务", {"杀掉猎人莱德雷和骑士杜尔根，然后向西瘟疫之地的科尔斯塔·迪普沙东复命。"}},
[6025] = {"未完的任务", {"进入壁炉谷并找一处高地，你可以在那里观察整个城镇并估算血色十字军的兵力，然后向西瘟疫之地的科尔斯塔·迪普沙东回报。"}},
[6027] = {"上古之书", {"拿到上古之书，将其交给艾瑟雷索塔中的阿佐尔·奥达蒙特。"}},
[6028] = {"永望镇报告", {"把永望镇报告送给西瘟疫地冰风岗的银色黎明军官普尔哈特。"}},
[6030] = {"尼古拉斯·瑟伦霍夫公爵", {"将《灵语研究》这本书交给东瘟疫之地圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫公爵。"}},
[6061] = {"驯服野兽", {"使用驯兽棒驯服成年陆行鸟。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。"}},
[6063] = {"驯服野兽", {"使用驯兽棒驯服树林潜伏者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。"}},
[6087] = {"驯服野兽", {"使用驯兽棒驯服一只草原捕食者。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。"}},
[6088] = {"驯服野兽", {"使用驯兽棒驯服一只猛鹫。练习你的技能，然后将驯服法杖交还给血蹄村的雅文·刺鬃。"}},
[6089] = {"训练野兽", {"与雷霆崖猎人高地的浩特·雷角谈一谈。"}},
[6101] = {"驯服野兽", {"使用驯兽棒驯服一只夜刃捕食者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。"}},
[6102] = {"驯服野兽", {"使用驯兽棒驯服一只巨翼恶枭。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。"}},
[6103] = {"训练野兽", {"与达纳苏斯塞纳里奥区的祖卡斯特谈一谈。"}},
[6121] = {"新的课程", {"到月光林地去，与永夜港的德迪利特·星焰谈一谈。"}},
[6122] = {"毒水之源", {"使用空的峭壁之泉取样器在瀑布洞口获得水样。","","将盛满的峭壁之泉取样器送到黑海岸奥伯丁的奥兰达利亚·夜歌那里。"}},
[6123] = {"收集解药", {"收集5个地根草和12个月亮菇，把它们交给奥伯丁的奥兰达利亚·夜歌，这样她就可以制作解药了。"}},
[6124] = {"消除疾病", {"对黑海岸的10头生病的鹿使用动物医疗药膏，以此来治疗它们。从壁泉河到奥伯丁，直到最南端靠近灰谷的地区都有生病的鹿出没。"}},
[6125] = {"解毒之术", {"回到达纳苏斯塞纳里奥区的玛斯雷·驭熊者那里。"}},
[6126] = {"新的课程", {"到月光林地去，与永夜港的德迪利特·星焰谈一谈。"}},
[6127] = {"毒水之源", {"使用空的鬼雾峰取样器在山顶取水样。","","将盛满的鬼雾峰取样器送到贫瘠之地十字路口的图加·符文图腾那里。"}},
[6128] = {"收集解药", {"收集5个地根草和5个科多兽角，把它们交给十字路口的图加·符文图腾，这样他就可以制作解药了。"}},
[6129] = {"消除疾病", {"对贫瘠之地北部的10只生病的瞪羚使用动物医疗药膏，以此来治疗它们。在穿过十字路口的那条东西走向的大路北面到处都是生病的蹬羚。"}},
[6130] = {"解毒之术", {"回到雷霆崖长者高地的图拉克·符文图腾那里。"}},
[6132] = {"救我出去！", {"护送梅丽萨，然后与科多兽坟场的霍恩尼兹谈一谈。"}},
[6134] = {"幽灵电浆", {"把幽灵磁铁箱和8份幽灵电浆交给凄凉之地的霍恩尼兹。"}},
[6141] = {"安东修士", {"与凄凉之地的安东修士谈一谈。"}},
[6142] = {"蚌肉鱼饵", {"找到10块软壳蚌肉，把它们交给葬影村的麦拉斯。"}},
[6143] = {"另一种鱼", {"杀死7个滑刃侍从、7个滑刃纳迦，以及5个滑刃巫师，然后与葬影村的杜泽加尔谈谈。"}},
[6161] = {"拉克摩尔的财宝！", {"找到拉克摩尔的银钥匙和金钥匙。找到并打开拉克摩尔的箱子。"}},
[6181] = {"快递消息", {"将刘易斯的便笺交给狮鹫管理员索尔。"}},
[6261] = {"杜加尔·朗德瑞克", {"将奥斯瑞克的箱子交给狮鹫管理员杜加尔·朗德瑞克。"}},
[6281] = {"赶赴暴风城", {"从狮鹫管理员索尔那里租用一头狮鹫，然后把刘易斯的便笺交给暴风城的奥斯瑞克·斯图恩。"}},
[6282] = {"鹰身人的威胁", {"烈日石居的马格兰要你去杀掉7个血怒鹰身人、7个血怒伏击者、7个血怒杀戮者和7个血怒游荡者。"}},
[6283] = {"血怒一族", {"烈日石居的马格兰要你去杀掉血怒撕裂者，然后把她的遗体带回来作为证据。"}},
[6284] = {"贝瑟莱斯", {"杀掉贝瑟莱斯，然后把贝瑟莱斯的牙齿交给烈日石居的马格兰。"}},
[6285] = {"返回西部荒野", {"从狮鹫管理员杜加尔·朗德瑞克那里租用一头狮鹫飞到哨兵岭，然后将奥斯瑞克的箱子交给哨兵岭的刘易斯。"}},
[6301] = {"生生不息", {"烈日石居的塔姆拉·荒原想让你去收集10枚盖亚之种。"}},
[6321] = {"瑟伯切尔的补给", {"将博迪瑞格的订单交给卡洛斯·拉佐克。"}},
[6322] = {"迈克尔·加勒特", {"将高顿的箱子交给迈克尔·加勒特。"}},
[6323] = {"飞往幽暗城", {"从蝙蝠管理员卡洛斯·拉佐克那里租一只蝙蝠飞往幽暗城，然后将博迪瑞格的订单交给幽暗城里的高顿·温德哈姆。"}},
[6324] = {"向博迪瑞格回报", {"从蝙蝠管理员迈克尔·加勒特那儿租一只蝙蝠飞往瑟伯切尔，然后将高顿的箱子交给瑟伯切尔的亡灵卫兵博迪瑞格。"}},
[6341] = {"泰达希尔的渔业", {"将尼莎的货物交给维斯派塔斯。"}},
[6342] = {"飞往奥伯丁", {"从角鹰兽管理员维斯派塔斯那里租用一只角鹰兽飞到奥伯丁，然后将尼莎的货物交给莱尔德。"}},
[6343] = {"飞回泰达希尔", {"将莱尔德的回信交给尼莎·影歌。"}},
[6344] = {"尼莎·影歌", {"与尼莎·影歌谈一谈。"}},
[6361] = {"一捆兽皮", {"带着兽皮去找十字路口的迪弗拉克。"}},
[6362] = {"飞往雷霆崖", {"从双足飞龙管理员迪弗拉克那里租一只驭风者飞往雷霆崖，然后将这捆兽皮交给雷霆崖的安哈努。"}},
