[6384] = {"飞往奥格瑞玛", {"从双足飞龙管理员迪弗拉克那里租一只驭风者飞往奥格瑞玛，然后将扎尔夫的肉品交给奥格瑞玛的格雷什卡。"}},
[6385] = {"双足飞龙管理员多拉斯", {"将格雷什卡的信交给奥格瑞玛的多拉斯。"}},
[6386] = {"返回十字路口", {"从驭风者管理员多拉斯那里雇一只驭风者前往十字路口，然后将格雷什卡的信交给十字路口的扎尔夫。"}},
[6387] = {"荣誉学员", {"将布洛克的名单交给塞尔萨玛的索格拉姆·伯雷森。"}},
[6388] = {"格莱斯·瑟登", {"将荣誉锄交给铁炉堡的格莱斯·瑟登。"}},
[6391] = {"飞往铁炉堡", {"从狮鹫管理员索格拉姆·伯雷森那里租一只狮鹫飞往铁炉堡，然后将布洛克的名单交给铁炉堡的高尼尔·石趾。"}},
[6392] = {"向布洛克回复", {"从狮鹫管理员格莱斯·瑟登那里租用一头飞往塞尔萨玛的狮鹫，然后将荣誉锄交给塞尔萨玛的布洛克·寻石者。"}},
[6393] = {"元素战争", {"将10块焚火余烬交给烈日石居的苏纳曼。"}},
[6394] = {"塔兹利尔的镐", {"将塔兹利尔的镐还给塔兹利尔。"}},
[6395] = {"玛拉的遗愿", {"将塞缪尔·菲普斯的遗骸带到玛拉的坟墓去，然后回到新兵艾尔雷斯那里。"}},
[6401] = {"卡雅还活着", {"把这个好消息告诉烈日石居的塔姆拉·荒原。"}},
[6421] = {"滚岩峡谷", {"深入滚岩峡谷的洞穴中，为烈日石居的摩罗加尔取回10块共鸣水晶以供研究。"}},
[6441] = {"萨特之角", {"为碎木哨岗的皮克希尔收集16只萨特的角。"}},
