[6461] = {"盗窃的蜘蛛", {"玛拉卡金的辛吉拉要求你杀死10只深苔爬行者和7只深苔毒蜘蛛。"}},
[6462] = {"巨魔符咒", {"将8个巨魔符咒交给佐拉姆加前哨站的米苏瓦。"}},
[6481] = {"土灵的觉醒", {"使用魔化共鸣水晶打开共鸣桶，然后杀死高戈罗克。将这个消息告诉摩罗加尔，并把魔化共鸣水晶还给他。"}},
[6482] = {"鲁尔的自由", {"护送鲁尔，然后与慰藉之林的雅玛·雪蹄谈一谈。"}},
[6503] = {"灰谷先驱者", {"杀掉9个灰谷先驱者，然后回到碎木哨岗的库莱比那里。"}},
[6504] = {"丢失的书页", {"找到丢失的12页伐木机操作指南，把它们合并为第1、2、3章。然后带着这些书页回到碎木岗哨去找古尔达·怒痕。"}},
[6521] = {"邪恶的盟友", {"把玛克林大使的头颅交给幽暗城的瓦里玛萨斯。"}},
[6522] = {"邪恶的盟友", {"把小卷轴交给幽暗城的瓦里玛萨斯。"}},
[6523] = {"保护卡雅", {"护送卡雅·扁蹄回到阿帕拉耶营地，然后到石爪山东南边界附近的玛卡巴·扁蹄那里去复命。"}},
[6541] = {"向卡德拉克报到", {"到贫瘠之地北部的卡德拉克那里报到。"}},
[6542] = {"向卡德拉克报到", {"到贫瘠之地北部的卡德拉克那里报到。"}},
[6543] = {"战歌报告", {"打开报告集，把战歌报告交给战歌斥候、战歌信使和战歌侦查骑兵。把他们的最新报告交给贫瘠之地北部哨塔上的卡德拉克。"}},
[6544] = {"托雷克的突袭", {"保护在银翼哨站与杜瑞尔·月火作战的托雷克，然后向慰籍之林的埃尔托格·怒齿汇报胜利的消息。"}},
