[6561] = {"黑暗深渊中的邪恶", {"把暮光领主克尔里斯的头颅交给雷霆崖的巴珊娜·符文图腾。"}},
[6562] = {"帮助耶努萨克雷", {"与灰谷的耶努萨克雷谈一谈。"}},
[6563] = {"阿库麦尔水晶", {"收集20颗阿库麦尔蓝宝石，把它们交给灰谷的耶努萨克雷。"}},
[6564] = {"上古之神的仆从", {"把潮湿的便笺交给灰谷的耶努萨克雷。"}},
[6565] = {"上古之神的仆从", {"杀掉黑暗深渊里的洛古斯·杰特，然后向灰谷的耶努萨克雷复命。"}},
[6571] = {"战歌氏族的补给品", {"收集战歌氏族的补给品：战歌锯条、伐木绳、战歌之油，还有一箱战歌之斧。"}},
[6581] = {"战歌锯条", nil},
[6604] = {"被激怒的枭兽", {"与坠星村的加隆·石矛谈一谈。"}},
[6607] = {"钓鱼专家纳特·帕格", {"纳特·帕格要你钓到以下几种鱼：","","悲伤沼泽芦苇海岸的芦苇海岸大马哈鱼。","","凄凉之地萨瑟里斯海岸的萨瑟里斯虎鱼。","","菲拉斯沃丹提斯河的菲拉斯草鱼。","","荆棘谷野人海岸的野人海岸蓝色叉牙鱼。","","当你钓到这些鱼之后，就可以回到纳特·帕格那里去了！"}},
[6610] = {"蚌肉大餐", {"迪尔格·奎克里弗想要你收集这些原料：","","12只巨蛋。你可以在塔纳利斯的大鹏或是其它大型鸟类那里获得这种蛋。","","10块美味的蚌肉。你可以从任何蚌类身上获得这种原料！","","20块奥特兰克冷酪。去买就是了！","","收集好所有原料，然后把它们交给迪尔格。"}},
[6612] = {"我认识一个家伙…", {"到塔纳利斯沙漠的加基森去，与迪尔格·奎克里弗谈谈你的厨师生涯。"}},
[6621] = {"污林熊怪之王", {"把卡拉恩的旗子插到污林图腾堆中。不要让熊怪摧毁这面旗子。击败穆戈特酋长，将穆戈特的图腾交给佐拉姆加的卡拉恩·阿玛卡。"}},
[6622] = {"救死扶伤", {"使用急救绷带来治疗病人。你必须在6个病人死亡之前拯救15个病人。","","一定要牢记治疗的顺序！受致命伤的病人会很快死亡，其次是重伤病人，受普通伤的病人死亡得最慢。所以你最好在治疗那些受致命伤和重伤的病人之后再去治疗受普通伤的病人。"}},
[6623] = {"部落医疗队", {"到阿拉希高地的落锤镇去，与格里高利·维克托医生谈一谈关于加入部落外科医疗队的事宜。"}},
[6624] = {"救死扶伤", {"使用急救绷带来治疗病人。你必须在6个病人死亡之前拯救15个病人。","","一定要牢记治疗的顺序！受致命伤的病人会很快死亡，其次是重伤病人，受普通伤的病人死亡得最慢。所以你最好在治疗那些受致命伤和重伤的病人之后再去治疗受普通伤的病人。"}},
[6625] = {"联盟医疗队", {"到尘泥沼泽的塞拉摩去，与古斯塔夫·范沃森医生谈一谈关于加入联盟外科医疗队的事宜。"}},
[6626] = {"邪恶之地", {"杀掉8个剃刀沼泽护卫者、8个剃刀沼泽织棘者和8个亡首教徒，然后向剃刀高地入口处的麦雷姆·月歌复命。"}},
[6627] = {"知识试炼", {"成功回答布劳格·幽魂的问题，然后和他再次对话。他会一直在石爪山等你回答问题。"}},
[6628] = {"知识试炼", {"成功回答帕科瓦·芬塔拉斯的问题，然后再次和他对话。他会一直在幽暗城等你回答问题。"}},
[6629] = {"杀死格鲁迪格·暗云", {"杀掉格鲁迪格·暗云和6个恐怖图腾蛮兵，然后向石爪山东南面的玛卡巴·扁蹄复命。"}},
[6641] = {"鞭笞者沃尔沙", {"在穆格拉什寻找火盆的过程中保证他的安全。帮助他扑灭火盆，然后在与纳迦作战时保护他。","","如果你成功了，就回到佐拉姆加前哨站去，把鞭笞者沃尔沙的死讯通知给战歌信使。"}},
[6661] = {"捕捉矿道老鼠", {"使用捕鼠者之笛捕获5只矿道老鼠，把它们引到蒙提那儿去。别忘了退还笛子。"}},
[6662] = {"我的兄弟，尼普希", {"把装着神秘肉品的纸箱交给暴风城矿道地铁仓库的尼普希。"}},
[6681] = {"拉文霍德庄园", {"把拉文霍德徽记交给拉文霍德庄园的法拉德，庄园就坐落在希尔斯布莱德的群山之中。","","你的智慧将在这次旅途中得到考验。做好准备吧。"}},
[6701] = {"辛迪加徽章", nil},
[6921] = {"废墟之间", {"把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。"}},
[6922] = {"阿奎尼斯男爵", {"把奇怪的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。"}},
[6981] = {"发光的碎片", {"寻找更多有关这块噩梦碎片的信息。"}},
[7003] = {"被缩小的巨人", {"使用索尔宾的超级压缩器，把菲拉斯的任意巨人缩小到便于对付的体型。从缩小后的巨人身上收集15份微缩残渣，交给菲拉斯被遗忘的海岸码头上的索尔宾·范达瑟。"}},
[7028] = {"扭曲的邪恶", {"为凄凉之地的维洛收集25个瑟莱德丝水晶雕像。"}},
[7029] = {"维利塔恩的污染", {"在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。","","在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。","","治疗8株植物并杀死那些诺克赛恩幼体，然后向葬影村的瓦克·战痕复命。"}},
[7041] = {"维利塔恩的污染", {"在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。","","在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。","","治疗8株植物并杀死那些诺克赛恩幼体，然后向尼耶尔前哨站的塔琳德莉亚复命。"}},
[7044] = {"玛拉顿的传说", {"找回塞雷布拉斯节杖的两个部分：塞雷布拉斯魔棒和塞雷布拉斯钻石。","","然后设法和塞雷布拉斯对话。"}},
[7046] = {"塞雷布拉斯节杖", {"帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖。","","当仪式完成之后再和他谈谈。"}},
[7064] = {"大地的污染", {"杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。"}},
[7065] = {"大地的污染", {"杀死瑟莱德丝公主，然后回到凄凉之地尼耶尔前哨站的守护者玛兰迪斯那里复命。"}},
[7066] = {"生命之种", {"到月光林地去找到雷姆洛斯，将生命之种交给他。"}},
[7067] = {"贱民的指引", {"阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。"}},
[7068] = {"暗影残片", {"从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。"}},
[7070] = {"暗影残片", {"从玛拉顿收集10块暗影残片，然后把它们交给尘泥沼泽塞拉摩岛上的大法师特沃什。"}},
[7201] = {"最后的元素", {"前往黑石深渊，找回10份元素精华。你首先想到的是搜查魔像和魔像制造者。你还记得薇薇安·拉格雷含糊地提到过元素生物。"}},
[7261] = {"国王的命令", {"到希尔斯布莱德丘陵地区的奥特兰克山谷去。到那里之后，和哈格丁中尉谈谈。","","为了铜须的荣耀！"}},
[7321] = {"海龟汤", {"给塔伦米尔的克里斯托弗·杰弗寇特带去10块海龟肉和一些舒心草。"}},
[7342] = {"胆小鬼才用弓箭！", nil},
[7383] = {"大地之冠", {"用月亮井的水装满紫水晶瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。"}},
[7492] = {"莫沙彻营地", {"和菲拉斯莫沙彻营地的塔罗·刺蹄谈一谈。"}},
[7494] = {"羽月要塞", {"和菲拉斯羽月要塞的拉托尼库斯·月矛谈一谈。"}},
[7701] = {"悬赏：工头玛托留斯", {"那个叫做工头玛托留斯的黑铁矮人叛徒就藏在大熔炉的熔渣之池深处。","","杀死工头玛托留斯，将他的头颅交给灼热峡谷的侦查队长洛洛尔以换取你的奖励。"}},
[7721] = {"压缩器的动力", {"从菲拉斯被遗忘的海岸那里的海元素和巨型海元素身上获取10块水元素核心，把它们交给码头附近的索尔宾·范达瑟。"}},
[7722] = {"绝密配方！", {"在大熔炉的熔渣之池中的某个地方，你可以找到工头玛托留斯偷走的秘密设计图：炽热助熔剂。找到这些设计图，把它们还给灼热峡谷的大铁匠博恩奈特。"}},
[7723] = {"该死的手指头！", {"汉瑟尔·重拳让你杀掉20个重型作战傀儡。","","重型作战傀儡就在灼热峡谷的大熔炉附近。当你杀死足够多的傀儡后，就回去找汉瑟尔·重拳。"}},
[7724] = {"熔岩蜘蛛的威胁！", {"汉瑟尔·重拳要你在灼热峡谷杀死20只灼热熔岩蜘蛛。你可以在灼热峡谷的高地和熔岩池附近找到它们。","","杀死足够多的灼热熔岩蜘蛛后，回去向灼热峡谷的汉瑟尔·重拳复命。"}},
[7725] = {"更多被缩小的巨人！", nil},
[7726] = {"补充动力", nil},
[7727] = {"熏火龙", {"汉瑟尔·重拳让你去杀掉20个熏火龙。","","熏火龙侵占了熔渣之池中的那些岩浆池。熔渣之池就在灼热峡谷的大熔炉中。","","当你杀死足够数量的熏火龙后，就回去找汉瑟尔·重拳。"}},
[7728] = {"被盗：鼓风机和望远镜", {"找到冶炼鼓风机和侦查员的望远镜，把它们还给灼热峡谷的监工斯克兰格。","","你所知道的关于这些物品的惟一信息是：它们肯定是被黑铁矮人偷走的。冶炼鼓风机是铁匠用的锻造工具，侦查员的望远镜是侦查员所需的侦查工具。"}},
[7729] = {"工作机会：肃清竞争对手", {"杀死15个黑铁工头和15个黑铁奴隶贩子。完成任务之后就回去找监工斯克兰格。"}},
[7730] = {"祖卡什的入侵", {"把20块祖卡什虫壳交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。"}},
[7731] = {"毒刺鞭笞者", {"击败痛苦深渊中的毒刺鞭笞者，把它的腺体交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。"}},
[7732] = {"祖卡什报告", {"把莫沙彻营地祖卡什报告交给奥格瑞玛暗巷区的基尔兹宾·鼓眼。"}},
[7733] = {"更高的品质", {"把10块怒痕雪人的毛皮交给菲拉斯羽月要塞的普拉特·马克格鲁比。"}},
[7734] = {"更高的品质", {"把10块怒痕雪人的毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。"}},
[7791] = {"捐献毛料", nil},
[7792] = {"捐献毛料", nil},
[7795] = {"捐献符文布", nil},
[7798] = {"捐献丝绸", nil},
