[8461] = {"北方的死木熊怪", {"格拉兹要你去杀死6个死木守卫、6个死木复仇者和6个死木萨满祭司。"}},
[8462] = {"与纳菲恩交谈", {"沿着路去费伍德森林，和名叫纳菲恩的熊怪谈一谈。他站在木喉要塞的入口处。"}},
[8464] = {"冬泉熊怪的活动", {"萨尔法要你去击杀8个冬泉萨满祭司、8个冬泉巢穴守卫，以及8个冬泉巨熊怪。萨尔法就在冬泉谷的木喉要塞入口外。"}},
[8465] = {"与萨尔法交谈", {"穿过木喉要塞去冬泉谷。和萨尔法谈谈，他就在木喉要塞另一头的出口处。"}},
