[65601] = {"要爱就会受伤害", {"和奥格瑞玛的玛加尔谈一谈。"}},
[65602] = {"爱是什么？", {"取得木雕，把它交给暴风城法师区里的黑暗缚灵者加科因。"}},
[65603] = {"束缚", {"使用木雕召唤并制服一个夜魔，然后将木雕还给已宰的羔羊旅店的黑暗缚灵者加科因。"}},
[65604] = {"束缚", {"使用皱缩头巾召唤并征服一只夜魔，然后皱缩头巾还给奥格瑞玛的甘鲁尔·血眼。"}},
