[76156] = {"大地母亲与匿同在", {"潜入雷霆崖东南部的风险投资公司矿区，从冲击补给品货车中收集5个爆盐采矿炸弹，随后交给雷霆崖的巴通·阴影图腾。"}},
[76160] = {"大地母亲与匿同在", {"在雷霆崖北部收集8个风怒球果，在研钵和捣杵中使用它们，随后带着成果返回雷霆崖的巴通·阴影图腾处。"}},
[76240] = {"大地母亲与匿同在", {"购买或捕捉一条新鲜的闪亮小鱼，在雷霆崖的巴通·阴影图腾面前使用一套匕首将其大卸八块。"}},
[78088] = {"怪异的神器", {"将奥萨拉克斯宝珠带给灰谷梅伊瑟娜岗哨的净化者德尔格伦。"}},
[78089] = {"暴风城的建议", {"将奥萨拉克斯宝珠交给暴风城的纯洁的凯瑟琳。"}},
[78090] = {"另寻高见", {"在暴风城找到术士的密室，向他们讨教关于宝珠的建议。"}},
[78092] = {"必毁无疑", {"从灰谷的恶魔身上收集12个玛诺洛斯微粒。带着它们和奥萨拉克斯宝珠，前往屠魔峡谷的玛诺洛斯之矛处。"}},
