[86576] = {"血怒饰品", {"把15块闪光的太阳石带给摩罗加尔。"}},
[86577] = {"腐烂样本", {"将8份腐烂的熊器官和10份腐烂的狼器官交给科雷克·望天。"}},
[86585] = {"阵亡者的旗帜", {"举起铁炉堡的旗帜，引出穴居人劈头斧并将其消灭，然后向拉格弗斯上尉报告。"}},
