[86613] = {"挖掘工具", {"把6件挖掘工具交给麦格玛尔·落斧。"}},
[86614] = {"浪中银光", {"将刻有姓名缩写的银发夹物归原主。"}},
[86615] = {"条约义务", {"在蛮锤城堡里找出红石大使遗失的外交背包。"}},
