[94438] = {"神性一课", {"携带生命符记，使用它在毒蛛峡谷复活亡灵卫兵法尔甘。","","如果你遗失了生命符记，请返回丹妮莎·莫尔处重新领取。"}},
[94440] = {"神性一课", {"从毒蛛峡谷的血色十字军战士处取回血色十字军的攻击计划，随后返回班达里安堡，将其交给亡灵卫兵比尔穆斯。"}},
