[94465] = {"火焰的召唤", {"将眠炎火炬带给洛克莫丹的布拉尔迪·灰烬披风。"}},
[94466] = {"火焰的召唤", {"收集1份火焰焦油和1个试剂袋，交给洛克莫丹的布拉尔迪·灰烬披风。"}},
[94467] = {"火焰的召唤", {"击败火焰之魂，将余烬放入恒焰圣殿顶部的火盆。"}},
