[94480] = {"敌人的馈赠", {"将偷来的饲料交给洛格玛的戈尔格。"}},
[94481] = {"力量大餐", {"在训练场喂饱8名洛格玛受训者。"}},
[94483] = {"教教他们规矩", {"在河流以南消灭8个法霍德牧师和12个法霍德斥候。"}},
[94484] = {"令人不安的寂静", {"前往影风森林东北部，寻找并与埃莱盖尔·刺爪交谈。"}},
[94485] = {"贵妇之泪", {"收集8簇贵妇之泪苔藓。"}},
[94486] = {"包扎用的羽毛", {"在影风森林从影风尖啸幼兽身上收集20根羽毛。"}},
[94487] = {"遭弃与不配", {"从影风森林的奥拉凯斯步兵和奥拉凯斯逐风者身上收集10件染血的传家宝。"}},
[94488] = {"血脉的羁绊", {"击杀指挥官哈利恩，并将他的徽记交给影风森林的埃莱盖尔·刺爪。"}},
[94489] = {"背叛的伤痕", {"进入夜牙兽穴治疗7名德鲁伊，并在影风森林找到乔雷尔·风歌。"}},
[94490] = {"撕破的信件", {"将撕破的信件交给影风森林的埃莱盖尔·刺爪。"}},
[94491] = {"兽穴的命运", {"将信件交给瓦拉纳尔的洛瑟鲁姆，向他报告这儿发生的一切。"}},
[94494] = {"水之召唤", {"在洛克莫丹找到诺里克·洛克赛恩。"}},
[94495] = {"水之召唤", {"在湿地找到赫尔夫达娜·赛格伦德。"}},
[94497] = {"水之召唤", {"在赫尔夫达娜洞穴下方的瀑布底部，灌满空的棕色水囊，然后返回湿地交给她。"}},
[94499] = {"水之召唤", {"在石堡瀑布附近的鱼人夜行者处，灌满空的红色水囊，然后返回湿地交给赫尔夫达娜·赛格伦德。"}},
[94500] = {"水之召唤", {"在灰谷阿斯特兰纳的水域，灌满空的蓝色水囊，然后返回湿地交给赫尔夫达娜·赛格伦德。"}},
[94501] = {"水之召唤", {"将一瓶最纯净的水带给洛克莫丹的诺里克·洛克赛恩。"}},
[94502] = {"水之召唤", {"喝下水之灵契，涤净西部荒野斯特登的池塘的腐化。","事成后返回洛克莫丹诺里克处复命。"}},
[94503] = {"水之召唤", {"在西部荒野与水之魂交谈。"}},
[94505] = {"水之召唤", {"将水灵碎片带给洛克莫丹的诺里克·洛克赛恩。"}},
[94532] = {"豺狼人泛滥", {"为洛格玛的涅扎·血吻消灭8个赤脊山秘法师、8个赤脊山捕兽者和6个赤脊山蛮兵。"}},
[94533] = {"斯纳格尔的鼻子", {"在刺毛丘陵找到斯纳格尔，将其击杀，并把他的鼻子带给涅扎·血吻。"}},
