[97197] = {"火焰之地碎片", {"勇闯黑石深渊，为莫高雷的阿拉娜·风暴行者带回一份火焰之地碎片。"}},
[97203] = {"学习骑乘", {"向维尔玛·瓦纳姆学习初级骑术。"}},
[97204] = {"学习骑乘", {"向卡尔·雷歌学习初级骑术。"}},
[97220] = {"菲尔莫尔的委托", {"将门楼的货物送到贸易区提亚斯奶酪店的仓库入口处。"}},
[97222] = {"门楼的物资", {"将门楼货物搬上提亚斯奶酪店的二楼，并放在门外。"}},
[97223] = {"血爪族母", {"把血爪族母的蛋交给森金村的克萨尔迪。"}},
[97225] = {"被遗忘的洛阿神像", {"从回音群岛收集8尊被遗忘的洛阿神像，将它们交给森金村的加德林大师。"}},
[97234] = {"阅览室", {"将打包好的阅读材料送到暴风城图书馆。"}},
[97236] = {"吉希斯之牙", {"把吉希斯之牙交给奥达希尔那位研究蜘蛛的人。"}},
[97237] = {"书架寻书", {"在图书馆的各处找到所需的阅读材料，然后带给暴风城花园区的罗伊·勒维尔斯。"}},
[97242] = {"耶尔玛克的混合配方", {"从荣誉谷水流周围生长的香蒲和矛草上摘取一些枝条，然后把它们交给耶尔玛克药剂店里的考吉尔德。"}},
[97246] = {"午餐诱惑", {"前往博斯坦的火坑，告诉他萨托格要你亲自把午餐送给米吉。"}},
[97249] = {"最爱的食物", {"把午餐送到格罗玛什要塞后面，交给米吉。"}},
[97250] = {"错怪无辜，罪有应得", {"消灭在尘泥沼泽边境侵入贫瘠之地的联盟士兵，然后返回陶拉祖营地向步兵劳格玛复命。"}},
[97253] = {"零零碎碎", {"从棘齿城以南的海盗上层营地收集5把错综复杂的零件，然后交给棘齿城的卑鄙的维尼克斯。"}},
[97263] = {"你的包裹到了", {"送达埃尔德伦被错放的包裹。"}},
[97265] = {"痛恨怨怒", {"在凄凉之地的萨格隆击败各种怨怒萨特，然后返回葬影村的阿卡莱身边。"}},
[97275] = {"伍特急什么", {"把耶尔玛克的药水交给伍特。"}},
[97277] = {"格伦德与戈兹温", {"去西北面的山丘找到格伦德和戈兹温的营地，取回戈兹温的机械日志，并消灭雪豹潜伏者。"}},
[97279] = {"遗失的武器", {"收集6件被遗弃的训练武器，然后拿回去交给兽穴的克赞·荆条。"}},
[97281] = {"酝酿中的风暴", {"把黯淡的风暴宝珠带给枯水谷附近的雷兹拉克。"}},
[97282] = {"风暴潜能", {"把5个带电的雷霆蜥蜴器官带给枯水谷附近的雷兹拉克。"}},
[97284] = {"瓦拉里尔的复仇", {"前往凄凉之地的雷斧堡垒，消灭那里的火刃氏族兽人，然后回尼耶尔前哨站向瓦拉里尔·屠魔者复命。"}},
[97286] = {"研究特权", nil},
[97287] = {"精明的谈判", {"与达拉然附近的<name>法师茉德拉的影像对话。"}},
[97288] = {"无尽的折磨", {"把憎恶头颅带给幽暗城的大药剂师法拉尼尔。"}},
[97289] = {"无尽的折磨", {"将男爵的头颅带到幽暗城中奥斯玛尔的躯体旁。"}},
[97290] = {"无尽的折磨", {"将你的发现汇报给幽暗城的大药剂师法拉尼尔。"}},
[97291] = {"无尽的折磨", {"为幽暗城的大药剂师法拉尼尔收集药材：去贸易区找塔文·格瑞斯特拿一顶剧毒骨帽，在草药学训练师附近采点水疱草，最后去潜行者区找毒药商人买些苦楚精华。"}},
[97292] = {"无尽的折磨", {"替大药剂师法拉尼尔将嘶嘶血清注入奥斯玛尔躯体上方的仪器中。"}},
[97326] = {"以石为座", {"找来8块光滑的巨石，交给格罗玛什要塞后面的斯拉。"}},
[97328] = {"搜刮财物", {"从荆棘谷的祖昆达废墟夺回8批被盗的货物，并把你的战利品交给藏宝海湾的某个人。"}},
[97329] = {"钥匙在哪？", {"将在荆棘谷祖昆达废墟的巨魔身上找到的粗糙的钥匙，交给齐米克斯·喷火。"}},
[97331] = {"齐米克斯大逃亡", {"护送齐米克斯·喷火离开祖昆达废墟，然后向藏宝海湾的码头管理员罗兹基尔复命，告诉他你已经成功救人。"}},
[97332] = {"两次错付的信任", {"把那份两次重订的包裹交给河林爆破引线港的码头管理员维兹巴兹。"}},
[97378] = {"镜鳞", {"把镜鳞的翅膀带去交给雷霆崖的梅洛·石蹄。"}},
[97386] = {"格罗姆高的攻势", {"格罗姆高营地的指挥官阿格罗戈什要你前往莫什奥格食人魔山，杀死那里的食人魔。"}},
[97405] = {"噪音投诉", {"克纳兹·枪焰需要你在莫什奥格食人魔山消灭3名莫什奥格法师、3名莫什奥格好战者、3名莫什奥格虐待者和3名莫什奥格萨满祭司。"}},
[97420] = {"节约、再用、重修旧好", nil},
[97453] = {"痛斩杂草", {"铲除格罗姆高南方的6株食肉杂草，然后向格米尔的母亲报告。"}},
[97485] = {"高地传统", {"向草药供应商尼达购买一捆草药，向附魔供应商纳塔购买一捆雪松枝，向制皮供应商曼胡购买筋腱丝线，并向烹饪供应商纳尔购买仪式燧石和火绒。","","把这些物品组合起来，然后在猎人高地撒下熏香。"}},
[97530] = {"砂槌欠款", {"塔纳利斯热砂港的保安主管图拉·比尔吉维兹要你找回一只格外闪亮的手镯，它遗失在砂槌食人魔营地附近。"}},
[97534] = {"灰头土脸的生意", {"奎因要你找回7块沙漠废料，并在加基森交还给她。"}},
[97536] = {"侏儒垃圾", {"霍尔迪·水炉要你将一箱放射性废料倾倒在塔纳利斯沙漠中远离加基森和其他垃圾的安全地点，然后回去找他。"}},
[97538] = {"绘画颜料", {"雷霆崖的塔恩·冰蹄需要30份暗色湖的幽暗草荚。"}},
[97539] = {"丝滑缝合", {"将12份外科蛛丝交给阿拉希高地落锤镇的格里高利·维克托医生。"}},
[97540] = {"绿洲", {"为刚刚解了渴的图加指明道路，带他回到妻子托尔塔身边。"}},
[97558] = {"被遗忘者的皮", {"给舍伦尼·洛巴尔特带去8张夜行蝙蝠翼膜、6张夜行犬皮以及3张邪鳍鱼人皮。"}},
[97583] = {"扭起来。", {"购买一些营养丰富的泥浆怪淤泥，回去喂给你结识的那只小软泥怪。如果它显得没精打采，就再陪它跳支舞，重新吸引它的注意力。"}},
[97617] = {"安全检查", {"找回8件未研究的神器、一顶探险者协会采矿头盔和一把无瑕的鹤嘴锄，把它们交给位于洛克莫丹与荒芜之地交界处的多尔加隆。"}},
[97663] = {"补给与研究", {"在漫尘盆地消灭食人魔，找回穆斯哈雷失窃的补给品。用它们收集附近石刻的拓片后，返回卡加斯向穆斯哈雷复命。"}},
[97884] = {"阳光林地的武器店", {"前往河林的阳光林地，找回特雷曼恩家族锻造技术秘典。"}},
[97891] = {"争分夺秒送药水", {"在规定时限内，将不稳定药水交给炼金房的马丁·费尔本医生。"}},
[97894] = {"奥伯丁的生意", {"去黑海岸的奥伯丁找高尔博德·钢手看看情况。","","博古斯提过，暴风城港口最南边的码头有艘船能直达那里。"}},
