[98025] = {"通缉：贾伊瓦内尔", {"找到并消灭那只名叫贾伊瓦内尔的猫头鹰，然后拔下它的一根羽毛。最后一次有人瞧见这只黑色猫头鹰，还是在亚米萨兰废墟北边的山脚底下。拿着羽毛，去向奥伯丁的哨兵戈琳达·纳希恩报告贾伊瓦内尔的死讯。"}},
[98027] = {"闪亮的弯月项链", {"将新月项链交还给阿斯特兰纳的玛琳。"}},
[98028] = {"马里诺斯男爵", {"将这颗浑浊的水球，带去交给黑海岸古树之林的安努。"}},
[98042] = {"开玩笑也要有个限度……", {"从黑海岸主宰之剑的暮光信徒或暮光暴徒身上夺取一颗无双之眼，然后在奥伯丁里找到那个愿意接手这烫手山芋的人。"}},
[98046] = {"大地之冠", {"将排空的器皿送至达纳苏斯月神殿的拉瑞亚手中。"}},
[98059] = {"希尔斯布莱德的囤积", {"将密封的连队请求带进希尔斯布莱德的镇政厅，然后把它安放在记账桌上。"}},
[98065] = {"大地之冠", {"将月亮井残骸交予达纳苏斯月神殿的泰兰德·语风。"}},
[98067] = {"哨兵之目", {"替达纳苏斯月神殿里的哨兵达莉亚·炎刃，分别在塞纳里奥要塞下层的入口、达纳苏斯银行、工匠区旅店以及城市的大门处安置好哨兵猫头鹰。"}},
[98069] = {"失窃的乱风岗补给品", {"将8份失窃的乱风岗补给品带给乱风岗的詹迪亚。"}},
[98070] = {"阻止尖啸", {"消灭5名尖啸鹰身人、5名尖啸游荡者以及5名尖啸唤风者。"}},
[98071] = {"酿酒师的交易", {"把几瓶陨鸦品种葡萄酒送到希尔斯布莱德丘陵东南方的丹加洛克，并带回一袋他们的自酿蛇麻草。"}},
[98072] = {"天上的鳄鱼", {"收集8片无瑕的赤红鳞片，把它们交给米奈希尔港的詹姆斯·哈洛兰。"}},
[98093] = {"肃清田野", {"贫瘠之地南部的苏尔哈萨需要你清理该区域内的7只雷鳞蜥蜴与7名乱齿捕猎者，以确保她能安全地离开大树。"}},
[98094] = {"支援斥候", {"高级执行官达萨利亚要求你，将最新的命令送去交给驻扎在塔伦米尔以南、丹加洛克外围的亡灵哨兵玛索吉。"}},
[98095] = {"宝贵制高点", {"亡灵哨兵玛索吉要你带上三只药剂师小瓶，将它们分别放置在希尔斯布莱德丘陵周围的山峰上，然后回去向他复命。"}},
[98096] = {"职责相系的姐妹", {"前往艾萨拉的塔伦迪斯营地，找指挥官真歌打听一下科尔达拉·炎刃的下落。"}},
[98155] = {"完好的杂毛兽皮", {"收集5张完好的杂毛兽皮，带回去交给克里斯蒂·格兰特。"}},
